window.PK=window.PK||{};window.PK.glossar=[{"slug":"5-amino-1mq","begriff":"5-Amino-1MQ","begriff_en":"5-Amino-1MQ","kategorie":"wirkstoff","kurz":"Klein molecuul onderzocht als een NNMT-remmer in preklinische modellen. Geen peptide.","kurz_en":"Klein molecuul onderzocht als een NNMT-remmer in preklinische modellen. Geen peptide.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 29155147","titel_en":"PubMed: Onderzoekspublicatie, PMID 29155147","url":"https://pubmed.ncbi.nlm.nih.gov/29155147/"}],"text":"Het gelinkte originele artikel onderzoekt kleine moleculaire NNMT-remmers in cellulaire assays en een dieet-geïnduceerde obesitasmodel bij muizen. Het biedt geen klinisch bewijs voor het gebruik van shopproducten.","text_en":"Het gelinkte originele artikel onderzoekt kleine moleculaire NNMT-remmers in cellulaire assays en een dieet-geïnduceerde obesitasmodel bij muizen. Het biedt geen klinisch bewijs voor het gebruik van shopproducten.","synonyme":["5-Amino 1MQ","5A1MQ","NNMT-remmer"],"synonyme_en":["5-Amino 1MQ","5A1MQ","NNMT-remmer"],"link":"wirkstoffe/5-amino-1mq.html"},{"slug":"affiliate-link","begriff":"Affiliatelink","begriff_en":"Affiliatelink","kategorie":"vergleich","kurz":"Een affiliate link leidt naar een externe winkel en kan een commissie activeren op een aankoop.","kurz_en":"Een affiliate link leidt naar een externe winkel en kan een commissie activeren op een aankoop.","quellen":[{"titel":"Peptide Compass: Onze affiliateverklaring","titel_en":"Peptide Compass: Onze affiliateverklaring","url":"https://peptidkompass.com/nl/affiliate-hinweis.html"}],"text":"Affiliatelinks dragen direct bij de link het label Advertentie en gebruiken bovendien het attribuut sponsored nofollow. Het label geldt ook voor winkellinks zonder bevestigd partnerschap. Partnerstatus en een mogelijke commissie veranderen niets aan hoe een leverancier wordt beoordeeld.","text_en":"Affiliatelinks dragen direct bij de link het label Advertentie en gebruiken bovendien het attribuut sponsored nofollow. Het label geldt ook voor winkellinks zonder bevestigd partnerschap. Partnerstatus en een mogelijke commissie veranderen niets aan hoe een leverancier wordt beoordeeld.","siehe":["partnercode"],"seiten":["affiliate-hinweis.html"]},{"slug":"agonist","begriff":"Agonist","begriff_en":"Agonist","kategorie":"grundlagen","kurz":"Een molecuul dat een receptor bindt en zijn signaalcascade activeert. Tegenhanger: antagonist.","kurz_en":"Een molecuul dat een receptor bindt en zijn signaalcascade activeert. Tegenhanger: antagonist.","quellen":[{"titel":"NCI: agonist","titel_en":"NCI: agonist","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/agonist"}],"text":"Een agonist bindt aan een receptor en activeert de signaalcascade die ermee verbonden is, vergelijkbaar met een sleutel die een slot opent. Het tegenovergestelde is een antagonist: het bindt ook aan de receptor maar activeert geen signaalcascade, in plaats daarvan de plek in beslag neemt en een agonist blokkeert om te binden. Studies gebruiken beide rollen om receptor signaalroutes op een gerichte manier te onderzoeken.","text_en":"Een agonist bindt aan een receptor en activeert de signaalcascade die ermee verbonden is, vergelijkbaar met een sleutel die een slot opent. Het tegenovergestelde is een antagonist: het bindt ook aan de receptor maar activeert geen signaalcascade, in plaats daarvan de plek in beslag neemt en een agonist blokkeert om te binden. Studies gebruiken beide rollen om receptor signaalroutes op een gerichte manier te onderzoeken.","siehe":["rezeptor","analogon"]},{"slug":"aliquot","begriff":"Aliquot","begriff_en":"Aliquot","kategorie":"handhabung","kurz":"Een aliquot is een kleine, gemeten portie die wordt genomen uit een grotere laboratoriumoplossing, meestal apart bewaard.","kurz_en":"Een aliquot is een kleine, gemeten portie die wordt genomen uit een grotere laboratoriumoplossing, meestal apart bewaard.","quellen":[{"titel":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","titel_en":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Een aliquot is een gescheiden monsterportie. Gescheiden porties kunnen herhaalde temperatuurcycli van de gehele voorraad vermijden.","text_en":"Een aliquot is een gescheiden monsterportie. Gescheiden porties kunnen herhaalde temperatuurcycli van de gehele voorraad vermijden.","siehe":["vial","konzentration","sterilitaet"]},{"slug":"aminosaeure","begriff":"Amino zuur","begriff_en":"Amino zuur","kategorie":"grundlagen","kurz":"De basisbouwsteen waaruit peptiden en eiwitten worden samengesteld via peptidebindingen.","kurz_en":"De basisbouwsteen waaruit peptiden en eiwitten worden samengesteld via peptidebindingen.","quellen":[{"titel":"NCI: amino zuur","titel_en":"NCI: amino zuur","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/amino-acid"}],"text":"Amino zuren bevatten een amino groep en een carboxyl groep. Eiwitten worden gebruikelijk beschreven met 20 standaard aminozuren. Peptidebindingen voegen ze samen tot ketens; hun volgorde wordt de sequentie genoemd.","text_en":"Amino zuren bevatten een amino groep en een carboxyl groep. Eiwitten worden gebruikelijk beschreven met 20 standaard aminozuren. Peptidebindingen voegen ze samen tot ketens; hun volgorde wordt de sequentie genoemd.","synonyme":["Amino zuren"],"synonyme_en":["Amino zuren"],"siehe":["peptid","peptidbindung","sequenz"],"seiten":["peptid-1x1.html"]},{"slug":"analogon","begriff":"Analoog","begriff_en":"Analoog","kategorie":"grundlagen","kurz":"Een synthetisch gemodificeerde variant van een endogeen peptide met een licht gewijzigde structuur.","kurz_en":"Een synthetisch gemodificeerde variant van een endogeen peptide met een licht gewijzigde structuur.","quellen":[{"titel":"EMA: Semaglutide als GLP-1 analog","titel_en":"EMA: Semaglutide als GLP-1 analog","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Een analoog is een in het lab gemaakte variant van een natuurlijk voorkomend peptide waarbij individuele aminozuren zijn gewisseld, toegevoegd of verwijderd. Onderzoekers gebruiken dergelijke structurele veranderingen om eigenschappen zoals stabiliteit of receptorbindingsgedrag op een gerichte manier te bestuderen. Een voorbeeld is semaglutide, een analoog van het endogene hormoon GLP-1.","text_en":"Een analoog is een in het lab gemaakte variant van een natuurlijk voorkomend peptide waarbij individuele aminozuren zijn gewisseld, toegevoegd of verwijderd. Onderzoekers gebruiken dergelijke structurele veranderingen om eigenschappen zoals stabiliteit of receptorbindingsgedrag op een gerichte manier te bestuderen. Een voorbeeld is semaglutide, een analoog van het endogene hormoon GLP-1.","synonyme":["Analogia"],"synonyme_en":["Analogia"],"siehe":["peptid","fragment","agonist"]},{"slug":"antimikrobielles-peptid","begriff":"Antimicrobiële peptiden","begriff_en":"Antimicrobiële peptiden","kategorie":"klassen","kurz":"Antimicrobiële peptiden zijn onderdeel van de aangeboren immuunverdediging, geproduceerd in de huid en slijmvliezen.","kurz_en":"Antimicrobiële peptiden zijn onderdeel van de aangeboren immuunverdediging, geproduceerd in de huid en slijmvliezen.","quellen":[{"titel":"NCBI Bookshelf: Aangeboren immuunsysteem","titel_en":"NCBI Bookshelf: Aangeboren immuunsysteem","url":"https://www.ncbi.nlm.nih.gov/books/NBK459455/"}],"text":"Antimicrobiële peptiden, ook wel AMP's of gastheerverdedigende peptiden genoemd, zijn onderdeel van de aangeboren immuunverdediging. Ze worden geproduceerd door huid- en slijmvliezencellen evenals immuuncellen en dringen door de membranen van bacteriën, schimmels of virussen. De best bekende menselijke groep zijn de cathelicidines, waarvan de enige actieve menselijke vorm LL-37 is. Naast dit directe membraanmechanisme worden AMP's ook bestudeerd als signaalmoleculen van het immuunsysteem.","text_en":"Antimicrobiële peptiden, ook wel AMP's of gastheerverdedigende peptiden genoemd, zijn onderdeel van de aangeboren immuunverdediging. Ze worden geproduceerd door huid- en slijmvliezencellen evenals immuuncellen en dringen door de membranen van bacteriën, schimmels of virussen. De best bekende menselijke groep zijn de cathelicidines, waarvan de enige actieve menselijke vorm LL-37 is. Naast dit directe membraanmechanisme worden AMP's ook bestudeerd als signaalmoleculen van het immuunsysteem.","synonyme":["AMP's","Gastheerverdedigende peptiden"],"synonyme_en":["AMP's","Gastheerverdedigende peptiden"],"siehe":["protein","peptid"],"wirkstoffe":["ll-37"],"seiten":["peptid-1x1.html"]},{"slug":"aod-9604","begriff":"AOD-9604","begriff_en":"AOD-9604","kategorie":"wirkstoff","kurz":"Gemodificeerd groeihormoonfragment onderzocht in metabole studies.","kurz_en":"Gemodificeerd groeihormoonfragment onderzocht in metabole studies.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 11146367","titel_en":"PubMed: Onderzoekspublicatie, PMID 11146367","url":"https://pubmed.ncbi.nlm.nih.gov/11146367/"}],"text":"Het geciteerde originele artikel onderzoekt AOD-9604 in Zuckerratten. Bevindingen uit dit diermodel kunnen niet direct worden overgebracht naar mensen of producten die verkocht worden door onderzoeksleveranciers.","text_en":"Het geciteerde originele artikel onderzoekt AOD-9604 in Zuckerratten. Bevindingen uit dit diermodel kunnen niet direct worden overgebracht naar mensen of producten die verkocht worden door onderzoeksleveranciers.","synonyme":["Anti-obesmiddel 9604","Tyr-hGH-fragment 177-191"],"synonyme_en":["Anti-obesmiddel 9604","Tyr-hGH-fragment 177-191"],"link":"wirkstoffe/aod-9604.html"},{"slug":"arzneimittel","begriff":"Medicinale product","begriff_en":"Medicinale product","kategorie":"recht","kurz":"Een medisch product wordt juridisch gedefinieerd als een stof die bedoeld is om ziekte bij mensen te behandelen of te voorkomen.","kurz_en":"Een medisch product wordt juridisch gedefinieerd als een stof die bedoeld is om ziekte bij mensen te behandelen of te voorkomen.","quellen":[{"titel":"Duitse Geneesmiddelenwet, § 2: Definitie van geneesmiddelen","titel_en":"Duitse Geneesmiddelenwet, § 2: Definitie van geneesmiddelen","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"}],"text":"§ 2 van de Duitse Geneesmiddelenwet betreft stoffen op basis van hun beoogde ziektegerelateerde gebruik en bepaalde farmacologische, immunologische of metabole functies. De indeling staat los van de vergunning voor het in de handel brengen. Een RUO-label sluit de status als geneesmiddel niet automatisch uit.","text_en":"§ 2 van de Duitse Geneesmiddelenwet betreft stoffen op basis van hun beoogde ziektegerelateerde gebruik en bepaalde farmacologische, immunologische of metabole functies. De indeling staat los van de vergunning voor het in de handel brengen. Een RUO-label sluit de status als geneesmiddel niet automatisch uit.","synonyme":["Medicijn"],"synonyme_en":["Medicijn"],"siehe":["ruo","zulassung","rezeptpflicht"],"seiten":["peptid-1x1.html"]},{"slug":"association","begriff":"Associatie (versus causaliteit)","begriff_en":"Associatie (versus causaliteit)","kategorie":"studien","kurz":"Twee dingen komen samen voor. Dat alleen toont niet aan dat het ene het andere veroorzaakt.","kurz_en":"Twee dingen komen samen voor. Dat alleen toont niet aan dat het ene het andere veroorzaakt.","quellen":[{"titel":"NLM MeSH: Causality","titel_en":"NLM MeSH: Causality","url":"https://www.ncbi.nlm.nih.gov/mesh/68015984"}],"text":"Een associatie betekent dat twee kenmerken statistisch samen voorkomen, zoals een gewoonte en een gezondheidsuitkomst. Causaliteit betekent dat het ene het andere teweegbrengt. Observationeel onderzoek toont meestal alleen associaties, omdat confounders, een omgekeerde richting of toeval het verband kunnen verklaren. Voor oorzaak en gevolg is aanvullend bewijs nodig, zoals gerandomiseerde studies.","text_en":"Een associatie betekent dat twee kenmerken statistisch samen voorkomen, zoals een gewoonte en een gezondheidsuitkomst. Causaliteit betekent dat het ene het andere teweegbrengt. Observationeel onderzoek toont meestal alleen associaties, omdat confounders, een omgekeerde richting of toeval het verband kunnen verklaren. Voor oorzaak en gevolg is aanvullend bewijs nodig, zoals gerandomiseerde studies.","synonyme":["Correlatie","Causaliteit"],"synonyme_en":["Correlatie","Causaliteit"],"siehe":["confounder","observational-study","rct"],"seiten":["studien.html"]},{"slug":"bakteriostatisches-wasser","begriff":"Bacteriostatisch Water","begriff_en":"Bacteriostatisch Water","kategorie":"handhabung","kurz":"Bacteriostatisch water is steriel water met een conserveringsmiddel, meestal benzylalcohol, voor oplossingen die meer dan één keer worden gebruikt.","kurz_en":"Bacteriostatisch water is steriel water met een conserveringsmiddel, meestal benzylalcohol, voor oplossingen die meer dan één keer worden gebruikt.","quellen":[{"titel":"DailyMed: Bacteriostatisch water, samenstelling","titel_en":"DailyMed: Bacteriostatisch water, samenstelling","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=87d6e9dc-fe3b-4593-ac9a-d7493d1959c7"}],"text":"Bacteriostatisch betekent dat bacteriële groei wordt geremd. Samenstelling is productspecifiek; geneesmiddelen kunnen benzylalcohol bevatten. Deze beschrijving verifieert noch de compatibiliteit met een specifiek peptide noch de veiligheid van een winkelproduct.","text_en":"Bacteriostatisch betekent dat bacteriële groei wordt geremd. Samenstelling is productspecifiek; geneesmiddelen kunnen benzylalcohol bevatten. Deze beschrijving verifieert noch de compatibiliteit met een specifiek peptide noch de veiligheid van een winkelproduct.","synonyme":["BAC-water"],"synonyme_en":["BAC-water"],"siehe":["steriles-wasser","rekonstitution","sterilitaet"]},{"slug":"observational-study","begriff":"Observationeel onderzoek","begriff_en":"Observationeel onderzoek","kategorie":"studien","kurz":"Studie waarin mensen alleen worden geobserveerd of uitkomsten worden gemeten, zonder ingreep zoals een behandeling.","kurz_en":"Studie waarin mensen alleen worden geobserveerd of uitkomsten worden gemeten, zonder ingreep zoals een behandeling.","quellen":[{"titel":"NCI: observationeel onderzoek","titel_en":"NCI: observationeel onderzoek","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/observational-study"}],"text":"Bij observationeel onderzoek worden mensen geobserveerd of uitkomsten gemeten zonder dat onderzoekers het resultaat proberen te beïnvloeden, bijvoorbeeld door een behandeling. Cohortonderzoek is een voorbeeld. Omdat groepen niet willekeurig worden toegewezen, kan observationeel onderzoek associaties laten zien, maar geen oorzaak aantonen.","text_en":"Bij observationeel onderzoek worden mensen geobserveerd of uitkomsten gemeten zonder dat onderzoekers het resultaat proberen te beïnvloeden, bijvoorbeeld door een behandeling. Cohortonderzoek is een voorbeeld. Omdat groepen niet willekeurig worden toegewezen, kan observationeel onderzoek associaties laten zien, maar geen oorzaak aantonen.","synonyme":["Observationele studies"],"synonyme_en":["Observationele studies"],"siehe":["cohort-study","association","rct"],"seiten":["studien.html"]},{"slug":"bioregulator","begriff":"Bioregulatoren","begriff_en":"Bioregulatoren","kategorie":"klassen","kurz":"Bioregulatoren zijn zeer korte synthetische peptiden van twee tot vier aminozuren die worden bestudeerd op orgaan systemen.","kurz_en":"Bioregulatoren zijn zeer korte synthetische peptiden van twee tot vier aminozuren die worden bestudeerd op orgaan systemen.","quellen":[{"titel":"Khavinson et al. (2003): Genreguleringshypothese","titel_en":"Khavinson et al. (2003): Genreguleringshypothese","url":"https://pubmed.ncbi.nlm.nih.gov/14666197/"}],"text":"In delen van peptideonderzoek beschrijft deze term korte sequenties die worden onderzocht op betrokkenheid bij genregulatie. Het is geen regulatoire categorie die effectiviteit vaststelt. Individuele cellulaire bevindingen vestigen noch orgaan specifieke voordelen noch verlenging van de menselijke levensduur.","text_en":"In delen van peptideonderzoek beschrijft deze term korte sequenties die worden onderzocht op betrokkenheid bij genregulatie. Het is geen regulatoire categorie die effectiviteit vaststelt. Individuele cellulaire bevindingen vestigen noch orgaan specifieke voordelen noch verlenging van de menselijke levensduur.","synonyme":["Peptide bioregulatoren","Khavinson peptiden"],"synonyme_en":["Peptide bioregulatoren","Khavinson peptiden"],"siehe":["oligopeptid","peptid"],"wirkstoffe":["epitalon"],"seiten":["peptid-1x1.html"]},{"slug":"bioverfuegbarkeit","begriff":"Biobeschikbaarheid","begriff_en":"Biobeschikbaarheid","kategorie":"grundlagen","kurz":"Het aandeel van een stof dat onveranderd de bloedbaan bereikt en daar gemeten kan worden.","kurz_en":"Het aandeel van een stof dat onveranderd de bloedbaan bereikt en daar gemeten kan worden.","quellen":[{"titel":"NCBI Bookshelf: Drug biobeschikbaarheid","titel_en":"NCBI Bookshelf: Drug biobeschikbaarheid","url":"https://www.ncbi.nlm.nih.gov/books/NBK557852/"}],"text":"Biobeschikbaarheid geeft aan welk aandeel van een toegediende stof uiteindelijk onveranderd de systemische circulatie bereikt, gemeten als een percentage. Het hangt deels af van hoeveel de stof wordt afgebroken door enzymen, zoals via proteolyse, op zijn weg door het lichaam. Farmacokinetische studies bepalen de biobeschikbaarheid afzonderlijk voor verschillende toedieningswegen.","text_en":"Biobeschikbaarheid geeft aan welk aandeel van een toegediende stof uiteindelijk onveranderd de systemische circulatie bereikt, gemeten als een percentage. Het hangt deels af van hoeveel de stof wordt afgebroken door enzymen, zoals via proteolyse, op zijn weg door het lichaam. Farmacokinetische studies bepalen de biobeschikbaarheid afzonderlijk voor verschillende toedieningswegen.","siehe":["halbwertszeit","proteolyse"]},{"slug":"blindtest","begriff":"Blinde test","begriff_en":"Blinde test","kategorie":"labor","kurz":"Blinde test: de betrokkenen weten geen relevante details over het monster.","kurz_en":"Blinde test: de betrokkenen weten geen relevante details over het monster.","quellen":[{"titel":"Karanicolas et al. (2010): Blinding en zijn beperkingen","titel_en":"Karanicolas et al. (2010): Blinding en zijn beperkingen","url":"https://pubmed.ncbi.nlm.nih.gov/20858381/"},{"titel":"Peptide Compass: Methodologie en verificatiebeperkingen","titel_en":"Peptide Compass: Methodologie en verificatiebeperkingen","url":"https://peptidkompass.com/nl/methodik.html"}],"text":"In een geblindeerde laboratoriumtest wordt informatie over de oorsprong van een monster achtergehouden vóór analyse. Dit kan verwachtingsbias verminderen maar kan fouten of bias niet uitsluiten. Sampling, methoden en gedocumenteerde traceerbaarheid zijn nog steeds van belang. Peptide Compass voert geen eigen geblindeerde tests uit.","text_en":"In een geblindeerde laboratoriumtest wordt informatie over de oorsprong van een monster achtergehouden vóór analyse. Dit kan verwachtingsbias verminderen maar kan fouten of bias niet uitsluiten. Sampling, methoden en gedocumenteerde traceerbaarheid zijn nog steeds van belang. Peptide Compass voert geen eigen geblindeerde tests uit.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"bpc-157","begriff":"BPC-157","begriff_en":"BPC-157","kategorie":"wirkstoff","kurz":"Synthetisch peptide onderzocht in preklinische modellen.","kurz_en":"Synthetisch peptide onderzocht in preklinische modellen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 27847966","titel_en":"PubMed: Onderzoekspublicatie, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"De gelinkte cellulaire en dierproef onderzoekt bloedvatvorming en VEGFR2 signalering. Dergelijke preklinische bevindingen vestigen geen effectiviteit of veilige toepassing bij mensen.","text_en":"De gelinkte cellulaire en dierproef onderzoekt bloedvatvorming en VEGFR2 signalering. Dergelijke preklinische bevindingen vestigen geen effectiviteit of veilige toepassing bij mensen.","synonyme":["Body Protection Compound 157","PL 14736"],"synonyme_en":["Body Protection Compound 157","PL 14736"],"link":"wirkstoffe/bpc-157.html"},{"slug":"cagrilintid","begriff":"Cagrilintide","begriff_en":"Cagrilintide","kategorie":"wirkstoff","kurz":"Synthetisch amylin-analoog onderzocht in metabole onderzoek.","kurz_en":"Synthetisch amylin-analoog onderzocht in metabole onderzoek.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 34288673","titel_en":"PubMed: Onderzoekspublicatie, PMID 34288673","url":"https://pubmed.ncbi.nlm.nih.gov/34288673/"}],"text":"Het geciteerde ontwikkelingsdocument beschrijft de structuur en selectie van een langwerkend amylin-analoog. Een onderzoeksmedicijn moet worden onderscheiden van een onderzoekschemisch product verkocht onder dezelfde naam.","text_en":"Het geciteerde ontwikkelingsdocument beschrijft de structuur en selectie van een langwerkend amylin-analoog. Een onderzoeksmedicijn moet worden onderscheiden van een onderzoekschemisch product verkocht onder dezelfde naam.","synonyme":["AM833","NN9838"],"synonyme_en":["AM833","NN9838"],"link":"wirkstoffe/cagrilintid.html"},{"slug":"charge","begriff":"Batch","begriff_en":"Batch","kategorie":"labor","kurz":"Een batch is een enkele productielijn met zijn eigen batchnummer, het nummer waarnaar een CoA verwijst.","kurz_en":"Een batch is een enkele productielijn met zijn eigen batchnummer, het nummer waarnaar een CoA verwijst.","quellen":[{"titel":"ICH Q7: Productie, batches en analysecertificaten","titel_en":"ICH Q7: Productie, batches en analysecertificaten","url":"https://www.fda.gov/media/71518/download"}],"text":"Het batchnummer koppelt één specifieke fles aan het overeenkomstige rapport, wat een resultaat traceerbaar maakt. Een CoA zonder duidelijke batchverwijzing kan niet aan een daadwerkelijk product worden gekoppeld en zegt correspondingly weinig.","text_en":"Het batchnummer koppelt één specifieke fles aan het overeenkomstige rapport, wat een resultaat traceerbaar maakt. Een CoA zonder duidelijke batchverwijzing kan niet aan een daadwerkelijk product worden gekoppeld en zegt correspondingly weinig.","synonyme":["Batch","Lot"],"synonyme_en":["Batch","Lot"],"siehe":["coa","drittlabor"],"seiten":["charge-pruefen.html"]},{"slug":"chromatogramm","begriff":"Chromatogram","begriff_en":"Chromatogram","kategorie":"labor","kurz":"Een grafische weergave van chromatografische scheiding, bijvoorbeeld in HPLC.","kurz_en":"Een grafische weergave van chromatografische scheiding, bijvoorbeeld in HPLC.","quellen":[{"titel":"IUPAC Gold Book: Chromatogram","titel_en":"IUPAC Gold Book: Chromatogram","url":"https://goldbook.iupac.org/terms/view/C01071"}],"text":"Een chromatogram toont het detector signaal tijdens chromatografische scheiding. Pieken kunnen overlappen. Areapercentages zijn afhankelijk van de methode en detector en zijn geen automatisch massapercentages. Een chromatogram alleen bevestigt de peptide-identiteit niet.","text_en":"Een chromatogram toont het detector signaal tijdens chromatografische scheiding. Pieken kunnen overlappen. Areapercentages zijn afhankelijk van de methode en detector en zijn geen automatisch massapercentages. Een chromatogram alleen bevestigt de peptide-identiteit niet.","siehe":["hplc","reinheit"],"seiten":["peptid-1x1.html"]},{"slug":"cjc-1295","begriff":"CJC-1295","begriff_en":"CJC-1295","kategorie":"wirkstoff","kurz":"Synthetisch GHRH-analoog onderzocht in endocriene onderzoek.","kurz_en":"Synthetisch GHRH-analoog onderzocht in endocriene onderzoek.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 16352683","titel_en":"PubMed: Onderzoekspublicatie, PMID 16352683","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"text":"Het gelinkte artikel onderzoekt een langwerkend GHRH-analoog bij gezonde volwassenen. Het onderzochte verbinding moet worden onderscheiden van anders gemodificeerde vormen die worden aangeboden onder vergelijkbare handelsnamen.","text_en":"Het gelinkte artikel onderzoekt een langwerkend GHRH-analoog bij gezonde volwassenen. Het onderzochte verbinding moet worden onderscheiden van anders gemodificeerde vormen die worden aangeboden onder vergelijkbare handelsnamen.","synonyme":["CJC-1295 met DAC","DAC:GRF"],"synonyme_en":["CJC-1295 met DAC","DAC:GRF"],"link":"wirkstoffe/cjc-1295.html"},{"slug":"coa","begriff":"CoA","begriff_en":"CoA","kategorie":"labor","kurz":"Een CoA is een rapport gekoppeld aan een specifieke batch, dat het batchnummer, testmethode en waarden zoals zuiverheid of identiteit vermeldt.","kurz_en":"Een CoA is een rapport gekoppeld aan een specifieke batch, dat het batchnummer, testmethode en waarden zoals zuiverheid of identiteit vermeldt.","quellen":[{"titel":"ICH Q7: Productie, batches en analysecertificaten","titel_en":"ICH Q7: Productie, batches en analysecertificaten","url":"https://www.fda.gov/media/71518/download"}],"langform":"Certificaat van Analyse","langform_en":"Certificaat van Analyse","text":"De waarde van een CoA is afhankelijk van het batchnummer, aangezien dit een rapport aan één specifiek flesje koppelt. Een generiek monster CoA zonder link naar een echte batch zegt weinig over het daadwerkelijke product. Gangbare vermeldingen zijn zuiverheid, identiteit en soms een endotoxinewaarde.","text_en":"De waarde van een CoA is afhankelijk van het batchnummer, aangezien dit een rapport aan één specifiek flesje koppelt. Een generiek monster CoA zonder link naar een echte batch zegt weinig over het daadwerkelijke product. Gangbare vermeldingen zijn zuiverheid, identiteit en soms een endotoxinewaarde.","synonyme":["Certificaat van analyse","Testrapport"],"synonyme_en":["Certificaat van analyse","Testrapport"],"siehe":["charge","reinheit","identitaet","drittlabor"],"seiten":["charge-pruefen.html","peptid-1x1.html"]},{"slug":"datenbasis","begriff":"Bewijskracht","begriff_en":"Bewijskracht","kategorie":"vergleich","kurz":"Bewijskracht toont hoeveel van de vijf scorecriteria gedocumenteerd zijn voor een leverancier.","kurz_en":"Bewijskracht toont hoeveel van de vijf scorecriteria gedocumenteerd zijn voor een leverancier.","quellen":[{"titel":"Peptide Compass: Onze vergelijkingsmethodologie","titel_en":"Peptide Compass: Onze vergelijkingsmethodologie","url":"https://peptidkompass.com/nl/methodik.html"}],"text":"Omdat ontbrekende criteria worden weggelaten uit de scoreberekening en de resterende gewichten worden herverdeeld, kan één gedocumenteerd criterium alleen al een hoge waarde opleveren. Leveranciers met verschillende bewijskracht zijn daarom slechts gedeeltelijk vergelijkbaar. Het aantal gedocumenteerde criteria wordt naast de score weergegeven.","text_en":"Omdat ontbrekende criteria worden weggelaten uit de scoreberekening en de resterende gewichten worden herverdeeld, kan één gedocumenteerd criterium alleen al een hoge waarde opleveren. Leveranciers met verschillende bewijskracht zijn daarom slechts gedeeltelijk vergelijkbaar. Het aantal gedocumenteerde criteria wordt naast de score weergegeven.","siehe":["dokumentationsscore"],"seiten":["methodik.html"]},{"slug":"dihexa","begriff":"Dihexa","begriff_en":"Dihexa","kategorie":"wirkstoff","kurz":"Synthetisch angiotensin IV-analoog onderzocht in preklinische modellen.","kurz_en":"Synthetisch angiotensin IV-analoog onderzocht in preklinische modellen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 38489193","titel_en":"PubMed: Onderzoekspublicatie, PMID 38489193","url":"https://pubmed.ncbi.nlm.nih.gov/38489193/"},{"titel":"PubMed: Redaction van bezorgdheid over het vroege artikel","titel_en":"PubMed: Redaction van bezorgdheid over het vroege artikel","url":"https://pubmed.ncbi.nlm.nih.gov/34551989/"}],"text":"Dihexa wordt onderzocht in dierlijke modellen. Het vroege artikel met PMID 23055539 heeft een Expression of Concern en wordt hier niet behandeld als zeker bewijs. Het bijbehorende gelinkte artikel beschrijft een ratmodel en vestigt geen menselijk gebruik.","text_en":"Dihexa wordt onderzocht in dierlijke modellen. Het vroege artikel met PMID 23055539 heeft een Expression of Concern en wordt hier niet behandeld als zeker bewijs. Het bijbehorende gelinkte artikel beschrijft een ratmodel en vestigt geen menselijk gebruik.","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"synonyme_en":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"link":"wirkstoffe/dihexa.html"},{"slug":"dokumentationsscore","begriff":"Documentatiescore","begriff_en":"Documentatiescore","kategorie":"vergleich","kurz":"De documentatiescore toont hoeveel geverifieerde leveranciersclaims daadwerkelijk gedocumenteerd zijn.","kurz_en":"De documentatiescore toont hoeveel geverifieerde leveranciersclaims daadwerkelijk gedocumenteerd zijn.","quellen":[{"titel":"Peptide Compass: Onze vergelijkingsmethodologie","titel_en":"Peptide Compass: Onze vergelijkingsmethodologie","url":"https://peptidkompass.com/nl/methodik.html"}],"text":"De methodologie definieert vijf gewogen criteria. Momenteel dragen laboratoriumdocumentatie, juridische informatie en verzending bij; prijs en bereik blijven niet gescoord. Ontbrekende criteria worden weggelaten en de resterende gewichten worden genormaliseerd. De score is geen kwaliteitszegel of een productveiligheidsbeoordeling.","text_en":"De methodologie definieert vijf gewogen criteria. Momenteel dragen laboratoriumdocumentatie, juridische informatie en verzending bij; prijs en bereik blijven niet gescoord. Ontbrekende criteria worden weggelaten en de resterende gewichten worden genormaliseerd. De score is geen kwaliteitszegel of een productveiligheidsbeoordeling.","siehe":["datenbasis","coa"],"seiten":["methodik.html"]},{"slug":"doppelblind","begriff":"Dubbelblind studie","begriff_en":"Dubbelblind studie","kategorie":"studien","kurz":"Een studieopzet waarbij noch de deelnemers noch het personeel weten wie het actieve middel of placebo krijgt. Vermindert onbewuste bias.","kurz_en":"Een studieopzet waarbij noch de deelnemers noch het personeel weten wie het actieve middel of placebo krijgt. Vermindert onbewuste bias.","quellen":[{"titel":"NCI: dubbelblind studie","titel_en":"NCI: dubbelblind studie","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/double-blind-study"}],"text":"De deelnemers en de geblindeerde leden van het onderzoeksteam weten niet aan welke groep ze behoren. Dit kan verwachtings- en beoordelingsbias verminderen. Blinding is een kwaliteitskenmerk maar sluit andere methodologische fouten niet uit.","text_en":"De deelnemers en de geblindeerde leden van het onderzoeksteam weten niet aan welke groep ze behoren. Dit kan verwachtings- en beoordelingsbias verminderen. Blinding is een kwaliteitskenmerk maar sluit andere methodologische fouten niet uit.","synonyme":["Dubbelblinding","Dubbelblind"],"synonyme_en":["Dubbelblinding","Dubbelblind"],"siehe":["rct","placebo"],"seiten":["studien.html"]},{"slug":"drittlabor","begriff":"Derde partij laboratorium","begriff_en":"Derde partij laboratorium","kategorie":"labor","kurz":"Een derde partij laboratorium is een extern lab dat een monster onafhankelijk van de fabrikant of winkel test en documenteert.","kurz_en":"Een derde partij laboratorium is een extern lab dat een monster onafhankelijk van de fabrikant of winkel test en documenteert.","quellen":[{"titel":"ISO/IEC 17025:2017: Bekwaamheid van testlaboratoria","titel_en":"ISO/IEC 17025:2017: Bekwaamheid van testlaboratoria","url":"https://www.iso.org/standard/66912.html"}],"text":"Als een CoA een extern lab noemt, is het waardevol om te controleren of de naam op welke manier dan ook verifieerbaar is en of het accreditatie bezit zoals ISO 17025. Een blind test is een manier om een resultaat onafhankelijk te controleren bovenop dat.","text_en":"Als een CoA een extern lab noemt, is het waardevol om te controleren of de naam op welke manier dan ook verifieerbaar is en of het accreditatie bezit zoals ISO 17025. Een blind test is een manier om een resultaat onafhankelijk te controleren bovenop dat.","synonyme":["Extern laboratorium"],"synonyme_en":["Extern laboratorium"],"siehe":["coa","iso-17025","blindtest"],"seiten":["methodik.html","charge-pruefen.html"]},{"slug":"dsip","begriff":"DSIP","begriff_en":"DSIP","kategorie":"wirkstoff","kurz":"Delta slaapinducerend peptide, oorspronkelijk beschreven in dierlijke experimenten.","kurz_en":"Delta slaapinducerend peptide, oorspronkelijk beschreven in dierlijke experimenten.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 265572","titel_en":"PubMed: Onderzoekspublicatie, PMID 265572","url":"https://pubmed.ncbi.nlm.nih.gov/265572/"}],"text":"DSIP is geïsoleerd en experimenteel onderzocht in een vroeg konijnstudie. Zijn naam weerspiegelt de onderzoekshypothese op dat moment. Het vestigt geen betrouwbaar slaapeffect bij mensen.","text_en":"DSIP is geïsoleerd en experimenteel onderzocht in een vroeg konijnstudie. Zijn naam weerspiegelt de onderzoekshypothese op dat moment. Het vestigt geen betrouwbaar slaapeffect bij mensen.","synonyme":["Delta-slaapinducerend peptide","Delta-slaappeptide"],"synonyme_en":["Delta-slaapinducerend peptide","Delta-slaappeptide"],"link":"wirkstoffe/dsip.html"},{"slug":"ema","begriff":"EMA","begriff_en":"EMA","kategorie":"recht","kurz":"De EMA is het EU-agentschap dat centraal markttoelatingprocedures coördineert en beoordeelt.","kurz_en":"De EMA is het EU-agentschap dat centraal markttoelatingprocedures coördineert en beoordeelt.","quellen":[{"titel":"EMA: Evaluatie en autorisaties","titel_en":"EMA: Evaluatie en autorisaties","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"langform":"Europees Geneesmiddelenbureau","langform_en":"Europees Geneesmiddelenbureau","text":"De European Medicines Agency coördineert wetenschappelijke beoordeling in de gecentraliseerde EU-autorisatieprocedure en publiceert beoordelingsrapporten. De Europese Commissie neemt de autorisatiedecisie. Een EMA-rapport is geen testcertificaat voor producten die worden verkocht door een onderzoeksleverancier.","text_en":"De European Medicines Agency coördineert wetenschappelijke beoordeling in de gecentraliseerde EU-autorisatieprocedure en publiceert beoordelingsrapporten. De Europese Commissie neemt de autorisatiedecisie. Een EMA-rapport is geen testcertificaat voor producten die worden verkocht door een onderzoeksleverancier.","siehe":["zulassung","fda"]},{"slug":"endotoxin","begriff":"Endotoxine","begriff_en":"Endotoxine","kategorie":"labor","kurz":"Endotoxinen zijn componenten van de bacteriële celwand, waarbij de hoeveelheid in een monster meestal wordt gegeven in eenheden per milligram.","kurz_en":"Endotoxinen zijn componenten van de bacteriële celwand, waarbij de hoeveelheid in een monster meestal wordt gegeven in eenheden per milligram.","quellen":[{"titel":"FDA: Testen van pyrogenen en endotoxinen","titel_en":"FDA: Testen van pyrogenen en endotoxinen","url":"https://www.fda.gov/media/83477/download"}],"text":"Bacteriële endotoxinen zijn componenten van Gram-negatieve bacteriën. Resultaten gebruiken endotoxine-eenheden met een gespecificeerde referentiehoeveelheid. Tests omvatten conventionele LAL-methoden en recombinante reagentia. Endotoxine-testen, sterilitetstesten en chemische zuiverheidstesten beantwoorden verschillende vragen.","text_en":"Bacteriële endotoxinen zijn componenten van Gram-negatieve bacteriën. Resultaten gebruiken endotoxine-eenheden met een gespecificeerde referentiehoeveelheid. Tests omvatten conventionele LAL-methoden en recombinante reagentia. Endotoxine-testen, sterilitetstesten en chemische zuiverheidstesten beantwoorden verschillende vragen.","siehe":["sterilitaet","coa"],"seiten":["methodik.html"]},{"slug":"epitalon","begriff":"Epitalon","begriff_en":"Epitalon","kategorie":"wirkstoff","kurz":"Synthetisch tetrapeptide onderzocht in celculturen voor telomeraseactiviteit.","kurz_en":"Synthetisch tetrapeptide onderzocht in celculturen voor telomeraseactiviteit.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 12937682","titel_en":"PubMed: Onderzoekspublicatie, PMID 12937682","url":"https://pubmed.ncbi.nlm.nih.gov/12937682/"}],"text":"Het geciteerde artikel onderzoekt epithalon in menselijke fibroblastcelculturen. Observaties van telomerase in geïsoleerde cellen vestigen geen verlenging van de menselijke levensduur.","text_en":"Het geciteerde artikel onderzoekt epithalon in menselijke fibroblastcelculturen. Observaties van telomerase in geïsoleerde cellen vestigen geen verlenging van de menselijke levensduur.","synonyme":["Epithalon","AEDG-tetrapeptide"],"synonyme_en":["Epithalon","AEDG-tetrapeptide"],"link":"wirkstoffe/epitalon.html"},{"slug":"fallbericht","begriff":"Casusrapport","begriff_en":"Casusrapport","kategorie":"studien","kurz":"Een gedetailleerd verslag van één, vaak ongebruikelijk geval. Biedt een vroege aanwijzing maar geen statistisch bewijs.","kurz_en":"Een gedetailleerd verslag van één, vaak ongebruikelijk geval. Biedt een vroege aanwijzing maar geen statistisch bewijs.","quellen":[{"titel":"NCI: casusrapport","titel_en":"NCI: casusrapport","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/case-report"}],"text":"Een casusrapport beschrijft observaties bij één persoon of een kleine groep gevallen, vaak een ongebruikelijke reactie of een zeldzaam evenement. Het kan verdere onderzoek aansturen, maar het heeft geen controlegroep en geen statistische analyse. Een casusrapport alleen bewijst geen algemeen effect.","text_en":"Een casusrapport beschrijft observaties bij één persoon of een kleine groep gevallen, vaak een ongebruikelijke reactie of een zeldzaam evenement. Het kan verdere onderzoek aansturen, maar het heeft geen controlegroep en geen statistische analyse. Een casusrapport alleen bewijst geen algemeen effect.","synonyme":["Casusrapport"],"synonyme_en":["Casusrapport"],"siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"fda","begriff":"FDA","begriff_en":"FDA","kategorie":"recht","kurz":"US-agentschap verantwoordelijk voor de regulering van medicijnen, voedsel en medische hulpmiddelen, onder andere producten.","kurz_en":"US-agentschap verantwoordelijk voor de regulering van medicijnen, voedsel en medische hulpmiddelen, onder andere producten.","quellen":[{"titel":"FDA: Wat het agentschap doet en niet goedkeurt","titel_en":"FDA: Wat het agentschap doet en niet goedkeurt","url":"https://www.fda.gov/consumers/consumer-updates/10-facts-about-what-fda-does-and-does-not-approve"}],"langform":"Amerikaanse voedsel- en geneesmiddelenautoriteit","langform_en":"Amerikaanse voedsel- en geneesmiddelenautoriteit","text":"De Food and Drug Administration reguleert medicijnen, voedsel en medische hulpmiddelen, onder andere producten, in de Verenigde Staten. Niet elke gereguleerde productcategorie krijgt voorafgaande goedkeuring. FDA-goedkeuring betreft een specifiek product en is geen EU-autorisatie.","text_en":"De Food and Drug Administration reguleert medicijnen, voedsel en medische hulpmiddelen, onder andere producten, in de Verenigde Staten. Niet elke gereguleerde productcategorie krijgt voorafgaande goedkeuring. FDA-goedkeuring betreft een specifiek product en is geen EU-autorisatie.","siehe":["zulassung","ema"]},{"slug":"fragment","begriff":"Fragment","begriff_en":"Fragment","kategorie":"grundlagen","kurz":"Een korte sectie van een groter endogeen peptide of eiwit, synthetisch gereproduceerd.","kurz_en":"Een korte sectie van een groter endogeen peptide of eiwit, synthetisch gereproduceerd.","quellen":[{"titel":"Purves et al.: Peptideneurotransmitters","titel_en":"Purves et al.: Peptideneurotransmitters","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Een fragment beslaat slechts een deel van de oorspronkelijke aminozuurketen van een peptide of eiwit, niet de volledige sequentie. Dergelijke gedeeltelijke sequenties worden gesynthetiseerd om te onderzoeken welk deel van een keten verantwoordelijk is voor bepaalde eigenschappen, zoals receptorbinding. Een bekend voorbeeld is thymosine alfa 1, een fragment van een groter precursor-eiwit.","text_en":"Een fragment beslaat slechts een deel van de oorspronkelijke aminozuurketen van een peptide of eiwit, niet de volledige sequentie. Dergelijke gedeeltelijke sequenties worden gesynthetiseerd om te onderzoeken welk deel van een keten verantwoordelijk is voor bepaalde eigenschappen, zoals receptorbinding. Een bekend voorbeeld is thymosine alfa 1, een fragment van een groter precursor-eiwit.","siehe":["peptid","analogon","sequenz"]},{"slug":"gegenion","begriff":"Tegenion","begriff_en":"Tegenion","kategorie":"labor","kurz":"Een tegenion is een zoutpartner van een peptide, meestal trifluoroacetaat (TFA) of acetaat, overgebleven van de productie.","kurz_en":"Een tegenion is een zoutpartner van een peptide, meestal trifluoroacetaat (TFA) of acetaat, overgebleven van de productie.","quellen":[{"titel":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","titel_en":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Een tegenion balanceert de elektrische lading. Tegenionen kunnen bijdragen aan het monstergewicht zonder deel uit te maken van de aminozuursequentie van het peptide.","text_en":"Een tegenion balanceert de elektrische lading. Tegenionen kunnen bijdragen aan het monstergewicht zonder deel uit te maken van de aminozuursequentie van het peptide.","siehe":["peptidgehalt","reinheit"],"seiten":["methodik.html"]},{"slug":"ghk-cu","begriff":"GHK-Cu","begriff_en":"GHK-Cu","kategorie":"wirkstoff","kurz":"Complex van het tripeptide GHK en koper onderzocht in verschillende preklinische modellen.","kurz_en":"Complex van het tripeptide GHK en koper onderzocht in verschillende preklinische modellen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 40672369","titel_en":"PubMed: Onderzoekspublicatie, PMID 40672369","url":"https://pubmed.ncbi.nlm.nih.gov/40672369/"}],"text":"GHK staat voor glycyl-histidyl-lysine. Het gerelateerde onderzoek onderzoekt het kopercomplex in een experimenteel colitismodel en cellulaire assays. Het is geen klinisch bewijs voor huidverzorging of andere toepassingen.","text_en":"GHK staat voor glycyl-histidyl-lysine. Het gerelateerde onderzoek onderzoekt het kopercomplex in een experimenteel colitismodel en cellulaire assays. Het is geen klinisch bewijs voor huidverzorging of andere toepassingen.","synonyme":["Glycyl-L-histidyl-L-lysine koper","Koper tripeptide-1"],"synonyme_en":["Glycyl-L-histidyl-L-lysine koper","Koper tripeptide-1"],"link":"wirkstoffe/ghk-cu.html"},{"slug":"ghrh","begriff":"GHRH","begriff_en":"GHRH","kategorie":"klassen","kurz":"GHRH is een hypothalamushormoon dat de hypofyse aanstuurt om groeihormoon vrij te geven.","kurz_en":"GHRH is een hypothalamushormoon dat de hypofyse aanstuurt om groeihormoon vrij te geven.","quellen":[{"titel":"Teichman et al. (2006): Onderzoek naar een GHRH-analoog","titel_en":"Teichman et al. (2006): Onderzoek naar een GHRH-analoog","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"langform":"Groeihormoon-afgeefhormoon","langform_en":"Groeihormoon-afgeefhormoon","text":"Groeihormoon-afgeefhormoon is een hypothalamuspeptide die via het hypofyseportal systeem naar de hypofyse gaat, waar het de afgifte van groeihormoon uit somatotrofe cellen triggert. Het maakt deel uit van de groeihormoonas en is het tegenhanger van het eigen remmer van het lichaam, somatostatin. Verschillende synthetische GHRH-analogen binden dezelfde receptor en worden in deze context bestudeerd of gebruikt.","text_en":"Groeihormoon-afgeefhormoon is een hypothalamuspeptide die via het hypofyseportal systeem naar de hypofyse gaat, waar het de afgifte van groeihormoon uit somatotrofe cellen triggert. Het maakt deel uit van de groeihormoonas en is het tegenhanger van het eigen remmer van het lichaam, somatostatin. Verschillende synthetische GHRH-analogen binden dezelfde receptor en worden in deze context bestudeerd of gebruikt.","synonyme":["Somatoliberine"],"synonyme_en":["Somatoliberine"],"siehe":["ghrp","wachstumshormon","rezeptor"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin"],"seiten":["peptid-1x1.html"]},{"slug":"ghrp","begriff":"GHRP","begriff_en":"GHRP","kategorie":"klassen","kurz":"GHRPs zijn synthetische peptiden die de afgifte van groeihormoon triggeren via de ghrelinreceptor.","kurz_en":"GHRPs zijn synthetische peptiden die de afgifte van groeihormoon triggeren via de ghrelinreceptor.","quellen":[{"titel":"Raun et al. (1998): Receptorbetrokkenheid bij GHRPs","titel_en":"Raun et al. (1998): Receptorbetrokkenheid bij GHRPs","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"langform":"Groeihormoon-afgeefpeptide","langform_en":"Groeihormoon-afgeefpeptide","text":"Groeihormoon-afgeefpeptiden zijn een klasse van synthetische peptiden die de ghrelinreceptor (GHS-R) binden om de afgifte van groeihormoon uit de hypofyse te triggeren. In tegenstelling tot GHRH-analogen gebruiken ze een afzonderlijk signaalpad en worden ze vaak gecombineerd met GHRH-analogen in onderzoek. De ghrelinreceptor is ook betrokken bij de regulering van honger en eetlust.","text_en":"Groeihormoon-afgeefpeptiden zijn een klasse van synthetische peptiden die de ghrelinreceptor (GHS-R) binden om de afgifte van groeihormoon uit de hypofyse te triggeren. In tegenstelling tot GHRH-analogen gebruiken ze een afzonderlijk signaalpad en worden ze vaak gecombineerd met GHRH-analogen in onderzoek. De ghrelinreceptor is ook betrokken bij de regulering van honger en eetlust.","synonyme":["GH secretagogues","Groeihormoon secretagogues"],"synonyme_en":["GH secretagogues","Groeihormoon secretagogues"],"siehe":["ghrh","wachstumshormon","rezeptor"],"wirkstoffe":["ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"gip","begriff":"GIP","begriff_en":"GIP","kategorie":"klassen","kurz":"GIP is een darmhormoon dat de insulineafgifte reguleert na koolhydraatrijke maaltijden.","kurz_en":"GIP is een darmhormoon dat de insulineafgifte reguleert na koolhydraatrijke maaltijden.","quellen":[{"titel":"NIDDK: Fundamenten van incretineonderzoek","titel_en":"NIDDK: Fundamenten van incretineonderzoek","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Glucose-afhankelijke insulinotropische polypeptide","langform_en":"Glucose-afhankelijke insulinotropische polypeptide","text":"Glucose-afhankelijke insulinotropische polypeptide is het tweede belangrijke incretinehormoon naast GLP-1. K cellen in de bovenste dunne darm geven het af na eten, en het bindt aan de GIP-receptor om de insulineafgifte te reguleren. Het is ook betrokken bij vetmetabolisme. Verschillende nieuwere diabetes en obesitas verbindingen combineren GIP met GLP-1 receptor agonisme.","text_en":"Glucose-afhankelijke insulinotropische polypeptide is het tweede belangrijke incretinehormoon naast GLP-1. K cellen in de bovenste dunne darm geven het af na eten, en het bindt aan de GIP-receptor om de insulineafgifte te reguleren. Het is ook betrokken bij vetmetabolisme. Verschillende nieuwere diabetes en obesitas verbindingen combineren GIP met GLP-1 receptor agonisme.","siehe":["glp-1","inkretin","rezeptor"],"wirkstoffe":["tirzepatid","retatrutid"],"seiten":["peptid-1x1.html"]},{"slug":"glp-1","begriff":"GLP-1","begriff_en":"GLP-1","kategorie":"klassen","kurz":"GLP-1 is een darmhormoon dat wordt vrijgegeven na eten en de insulineafgifte reguleert.","kurz_en":"GLP-1 is een darmhormoon dat wordt vrijgegeven na eten en de insulineafgifte reguleert.","quellen":[{"titel":"NIDDK: Fundamenten van incretineonderzoek","titel_en":"NIDDK: Fundamenten van incretineonderzoek","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Glucagon-achtig peptide 1","langform_en":"Glucagon-achtig peptide 1","text":"Glucagon-achtig peptide 1 is een incretinehormoon dat wordt vrijgegeven door L cellen in de dunne darm na eten. Het bindt de GLP-1 receptor, reguleert insulineafgifte, vertraagt de maaglediging en is betrokken bij verzadigingssignalisatie in de hersenen. Verschillende synthetische GLP-1 receptor agonisten richten zich op dit systeem, en sommige zijn goedgekeurd als geneesmiddelen.","text_en":"Glucagon-achtig peptide 1 is een incretinehormoon dat wordt vrijgegeven door L cellen in de dunne darm na eten. Het bindt de GLP-1 receptor, reguleert insulineafgifte, vertraagt de maaglediging en is betrokken bij verzadigingssignalisatie in de hersenen. Verschillende synthetische GLP-1 receptor agonisten richten zich op dit systeem, en sommige zijn goedgekeurd als geneesmiddelen.","synonyme":["Glucagon-achtig peptide-1"],"synonyme_en":["Glucagon-achtig peptide-1"],"siehe":["gip","inkretin","rezeptor","agonist"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"gmp","begriff":"GMP","begriff_en":"GMP","kategorie":"recht","kurz":"GMP is een erkende kwaliteitsstandaard voor de fabricage van geneesmiddelen en soortgelijke goederen.","kurz_en":"GMP is een erkende kwaliteitsstandaard voor de fabricage van geneesmiddelen en soortgelijke goederen.","quellen":[{"titel":"ICH Q7: Productie, batches en analysecertificaten","titel_en":"ICH Q7: Productie, batches en analysecertificaten","url":"https://www.fda.gov/media/71518/download"}],"langform":"Goede productiepraktijken","langform_en":"Goede productiepraktijken","text":"Good Manufacturing Practice omvat vereisten voor faciliteiten, processen, documentatie en traceerbaarheid in de productie. GMP is verplicht voornamelijk voor geautoriseerde geneesmiddelen. Een GMP-claim van een fabrikant vervangt niet onafhankelijke bewijzen zoals een openbare CoA en geldt alleen in de mate dat dit gedocumenteerd is.","text_en":"Good Manufacturing Practice omvat vereisten voor faciliteiten, processen, documentatie en traceerbaarheid in de productie. GMP is verplicht voornamelijk voor geautoriseerde geneesmiddelen. Een GMP-claim van een fabrikant vervangt niet onafhankelijke bewijzen zoals een openbare CoA en geldt alleen in de mate dat dit gedocumenteerd is.","siehe":["zulassung","coa"],"seiten":["methodik.html"]},{"slug":"halbwertszeit","begriff":"Halveringstijd","begriff_en":"Halveringstijd","kategorie":"grundlagen","kurz":"De tijd die nodig is om de concentratie van een stof in het lichaam te halveren.","kurz_en":"De tijd die nodig is om de concentratie van een stof in het lichaam te halveren.","quellen":[{"titel":"NCBI Bookshelf: Farmacokinetiek","titel_en":"NCBI Bookshelf: Farmacokinetiek","url":"https://www.ncbi.nlm.nih.gov/books/NBK557744/"}],"text":"Halveringstijd beschrijft hoe lang het duurt voordat de bloedconcentratie van een peptide daalt tot de helft van de beginwaarde. Het wordt gemeten in farmacokinetische studies en verschilt aanzienlijk tussen individuele peptiden, mede afhankelijk van hoe snel endogene enzymen de keten door proteolyse afbreken. Een kortere halveringstijd betekent een snellere afbraak dan een langere.","text_en":"Halveringstijd beschrijft hoe lang het duurt voordat de bloedconcentratie van een peptide daalt tot de helft van de beginwaarde. Het wordt gemeten in farmacokinetische studies en verschilt aanzienlijk tussen individuele peptiden, mede afhankelijk van hoe snel endogene enzymen de keten door proteolyse afbreken. Een kortere halveringstijd betekent een snellere afbraak dan een langere.","siehe":["proteolyse","bioverfuegbarkeit"]},{"slug":"hazard-ratio","begriff":"Hazard ratio (risicoverhouding)","begriff_en":"Hazard ratio (risicoverhouding)","kategorie":"studien","kurz":"Maat die vergelijkt hoe vaak een gebeurtenis in twee groepen in de loop van de tijd voorkomt. Een waarde van 1 betekent geen verschil.","kurz_en":"Maat die vergelijkt hoe vaak een gebeurtenis in twee groepen in de loop van de tijd voorkomt. Een waarde van 1 betekent geen verschil.","quellen":[{"titel":"NCI: hazard ratio","titel_en":"NCI: hazard ratio","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hazard-ratio"}],"text":"De hazard ratio (HR) vergelijkt hoe vaak een gebeurtenis, zoals ziekteprogressie, in de loop van de tijd in de ene groep optreedt ten opzichte van een andere groep. Een waarde van 1 betekent geen verschil; waarden boven of onder 1 laten zien in welke groep de gebeurtenis vaker optrad. Hij zegt niets over het absolute risico en wordt samen met een betrouwbaarheidsinterval gelezen.","text_en":"De hazard ratio (HR) vergelijkt hoe vaak een gebeurtenis, zoals ziekteprogressie, in de loop van de tijd in de ene groep optreedt ten opzichte van een andere groep. Een waarde van 1 betekent geen verschil; waarden boven of onder 1 laten zien in welke groep de gebeurtenis vaker optrad. Hij zegt niets over het absolute risico en wordt samen met een betrouwbaarheidsinterval gelezen.","synonyme":["HR"],"synonyme_en":["HR"],"siehe":["confidence-interval","cohort-study","rct"],"seiten":["studien.html"]},{"slug":"hexarelin","begriff":"Hexarelin","begriff_en":"Hexarelin","kategorie":"wirkstoff","kurz":"Synthetisch peptide onderzocht in studies van de groeihormoonas.","kurz_en":"Synthetisch peptide onderzocht in studies van de groeihormoonas.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 7910650","titel_en":"PubMed: Onderzoekspublicatie, PMID 7910650","url":"https://pubmed.ncbi.nlm.nih.gov/7910650/"}],"text":"Het geciteerde originele artikel beschrijft hexarelin als een synthetisch peptide en onderzoekt groeihormoonafgifte bij ratten. Dergelijke modelbevindingen vestigen geen veilige menselijke toepassing.","text_en":"Het geciteerde originele artikel beschrijft hexarelin als een synthetisch peptide en onderzoekt groeihormoonafgifte bij ratten. Dergelijke modelbevindingen vestigen geen veilige menselijke toepassing.","link":"wirkstoffe/hexarelin.html"},{"slug":"hplc","begriff":"HPLC","begriff_en":"HPLC","kategorie":"labor","kurz":"HPLC is de standaard analytische methode die wordt gebruikt om de zuiverheid van een peptidemonster als percentage te bepalen.","kurz_en":"HPLC is de standaard analytische methode die wordt gebruikt om de zuiverheid van een peptidemonster als percentage te bepalen.","quellen":[{"titel":"FDA: Analyse van complexe mengsels en peptiden","titel_en":"FDA: Analyse van complexe mengsels en peptiden","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"langform":"Hoge-prestatie vloeistofchromatografie","langform_en":"Hoge-prestatie vloeistofchromatografie","text":"De methode scheidt een monster in zijn componenten en meet elk van hen, wat een chromatogram oplevert met één piek per component. De oppervlakte van de hoofdpiek geeft de vermelde zuiverheidswaarde aan. HPLC alleen zegt niets over de identiteit, dat vereist ook massaspectrometrie.","text_en":"De methode scheidt een monster in zijn componenten en meet elk van hen, wat een chromatogram oplevert met één piek per component. De oppervlakte van de hoofdpiek geeft de vermelde zuiverheidswaarde aan. HPLC alleen zegt niets over de identiteit, dat vereist ook massaspectrometrie.","synonyme":["Hoge-prestatie vloeistofchromatografie"],"synonyme_en":["Hoge-prestatie vloeistofchromatografie"],"siehe":["reinheit","chromatogramm","massenspektrometrie"],"seiten":["methodik.html","peptid-1x1.html"]},{"slug":"hwg","begriff":"HWG","begriff_en":"HWG","kategorie":"recht","kurz":"De HWG reguleert de reclame van geneesmiddelen en therapeutische methoden aan het publiek in Duitsland.","kurz_en":"De HWG reguleert de reclame van geneesmiddelen en therapeutische methoden aan het publiek in Duitsland.","quellen":[{"titel":"De Duitse Gesetz über Werbung im Gesundheitssystem, officiële tekst","titel_en":"De Duitse Gesetz über Werbung im Gesundheitssystem, officiële tekst","url":"https://www.gesetze-im-internet.de/heilmwerbg/"}],"langform":"Wet op de reclame voor geneesmiddelen","langform_en":"Wet op de reclame voor geneesmiddelen","text":"De Duitse Wet op de reclame voor geneesmiddelen beperkt hoe geneesmiddelen en behandelmethoden publiekelijk mogen worden beschreven, inclusief claims over ziekte of menselijk gebruik. Daarom beschrijft Peptide Compass stoffen alleen in termen van onderzoeksbevindingen en doet geen uitspraken over een effect in het lichaam van de lezer.","text_en":"De Duitse Wet op de reclame voor geneesmiddelen beperkt hoe geneesmiddelen en behandelmethoden publiekelijk mogen worden beschreven, inclusief claims over ziekte of menselijk gebruik. Daarom beschrijft Peptide Compass stoffen alleen in termen van onderzoeksbevindingen en doet geen uitspraken over een effect in het lichaam van de lezer.","siehe":["arzneimittel"],"seiten":["methodik.html"]},{"slug":"identitaet","begriff":"Identiteit","begriff_en":"Identiteit","kategorie":"labor","kurz":"Identiteit, bevestigd door massaspectrometrie, verifieert dat een monster daadwerkelijk het genoemde peptide bevat.","kurz_en":"Identiteit, bevestigd door massaspectrometrie, verifieert dat een monster daadwerkelijk het genoemde peptide bevat.","quellen":[{"titel":"FDA: Analyse van complexe mengsels en peptiden","titel_en":"FDA: Analyse van complexe mengsels en peptiden","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Dit wordt meestal getoond via LC-MS, een combinatie van vloeistofchromatografie en massaspectrometrie die het molecuulgewicht meet. Zuiverheid en identiteit zijn twee afzonderlijke gegevens, en een compleet CoA vermeldt beide. Zuiverheid alleen bewijst niet welke molecuul er daadwerkelijk aanwezig is.","text_en":"Dit wordt meestal getoond via LC-MS, een combinatie van vloeistofchromatografie en massaspectrometrie die het molecuulgewicht meet. Zuiverheid en identiteit zijn twee afzonderlijke gegevens, en een compleet CoA vermeldt beide. Zuiverheid alleen bewijst niet welke molecuul er daadwerkelijk aanwezig is.","siehe":["massenspektrometrie","reinheit","coa"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1","begriff":"IGF-1","begriff_en":"IGF-1","kategorie":"klassen","kurz":"IGF-1 is een hormoon dat voornamelijk in de lever wordt geproduceerd als reactie op groeihormoon.","kurz_en":"IGF-1 is een hormoon dat voornamelijk in de lever wordt geproduceerd als reactie op groeihormoon.","quellen":[{"titel":"NIDDK: Groeihormoon en IGF-1","titel_en":"NIDDK: Groeihormoon en IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Insuline-achtig groeifactor 1","langform_en":"Insuline-achtig groeifactor 1","text":"Insuline-achtig groeifactor 1 wordt voornamelijk in de lever geproduceerd, getriggerd door de binding van groeihormoon aan levercellen, en circuleert in het bloed grotendeels gebonden aan dragerproteïnen. Het bindt de IGF-1 receptor en mediatieert een groot deel van het effect van groeihormoon op spieren, botten en bindweefsel. Een IGF-1-analoog met een verlengde halfwaardetijd wordt in onderzoek gebruikt als een losstaand hulpmiddel, onafhankelijk van de eigen regulatie door het lichaam via groeihormoon.","text_en":"Insuline-achtig groeifactor 1 wordt voornamelijk in de lever geproduceerd, getriggerd door de binding van groeihormoon aan levercellen, en circuleert in het bloed grotendeels gebonden aan dragerproteïnen. Het bindt de IGF-1 receptor en mediatieert een groot deel van het effect van groeihormoon op spieren, botten en bindweefsel. Een IGF-1-analoog met een verlengde halfwaardetijd wordt in onderzoek gebruikt als een losstaand hulpmiddel, onafhankelijk van de eigen regulatie door het lichaam via groeihormoon.","synonyme":["Somatomedin C"],"synonyme_en":["Somatomedin C"],"siehe":["wachstumshormon","ghrh","rezeptor"],"wirkstoffe":["igf-1-lr3"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1-lr3","begriff":"IGF-1 LR3","begriff_en":"IGF-1 LR3","kategorie":"wirkstoff","kurz":"Gemodificeerd IGF-1-analoog onderzocht in preklinische modellen.","kurz_en":"Gemodificeerd IGF-1-analoog onderzocht in preklinische modellen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 7561636","titel_en":"PubMed: Onderzoekspublicatie, PMID 7561636","url":"https://pubmed.ncbi.nlm.nih.gov/7561636/"}],"text":"Het geciteerde artikel onderzoekt Long R3 IGF-I bij cavia’s en beschrijft een verminderde affiniteit voor IGF-bindende eiwitten. Bevindingen voor deze gemodificeerde vorm zijn niet uitwisselbaar met bevindingen voor endogeen IGF-1.","text_en":"Het geciteerde artikel onderzoekt Long R3 IGF-I bij cavia’s en beschrijft een verminderde affiniteit voor IGF-bindende eiwitten. Bevindingen voor deze gemodificeerde vorm zijn niet uitwisselbaar met bevindingen voor endogeen IGF-1.","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"synonyme_en":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"link":"wirkstoffe/igf-1-lr3.html"},{"slug":"in-vitro","begriff":"In vitro","begriff_en":"In vitro","kategorie":"studien","kurz":"Een test buiten een levend organisme, meestal op celculturen. Het zegt niets over een effect bij mensen.","kurz_en":"Een test buiten een levend organisme, meestal op celculturen. Het zegt niets over een effect bij mensen.","quellen":[{"titel":"NCI: in vitro","titel_en":"NCI: in vitro","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vitro"}],"text":"In vitro studies onderzoeken geïsoleerde cellen of moleculen in een gecontroleerde omgeving zoals een petrischaal. Ze kunnen vroege biochemische effecten laten zien, maar de celcontext vervangt geen heel organisme. Dit soort gegevens telt als labonderzoek en vertaalt zich niet naar mensen.","text_en":"In vitro studies onderzoeken geïsoleerde cellen of moleculen in een gecontroleerde omgeving zoals een petrischaal. Ze kunnen vroege biochemische effecten laten zien, maar de celcontext vervangt geen heel organisme. Dit soort gegevens telt als labonderzoek en vertaalt zich niet naar mensen.","synonyme":["in vitro"],"synonyme_en":["in vitro"],"siehe":["in-vivo","praeklinisch","tiermodell"],"seiten":["studien.html"]},{"slug":"in-vivo","begriff":"In vivo","begriff_en":"In vivo","kategorie":"studien","kurz":"Een onderzoek in een levend organisme. De term alleen onderscheidt dierlijke gegevens van menselijke gegevens niet.","kurz_en":"Een onderzoek in een levend organisme. De term alleen onderscheidt dierlijke gegevens van menselijke gegevens niet.","quellen":[{"titel":"NCI: in vivo","titel_en":"NCI: in vivo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vivo"}],"text":"In vivo betekent dat een onderzoek plaatsvindt in een levend organisme. Dit kan een dier of een mens zijn. Onderzoeksresultaten moeten daarom het bestudeerde model identificeren. Dierlijke resultaten kunnen niet direct naar mensen worden overgeheveld.","text_en":"In vivo betekent dat een onderzoek plaatsvindt in een levend organisme. Dit kan een dier of een mens zijn. Onderzoeksresultaten moeten daarom het bestudeerde model identificeren. Dierlijke resultaten kunnen niet direct naar mensen worden overgeheveld.","synonyme":["in vivo"],"synonyme_en":["in vivo"],"siehe":["in-vitro","tiermodell","praeklinisch"],"seiten":["studien.html"]},{"slug":"inkretin","begriff":"Incretine","begriff_en":"Incretine","kategorie":"klassen","kurz":"Incretines zijn darmhormonen die vrijkomen na eten en betrokken zijn bij de regulering van insulineafgifte.","kurz_en":"Incretines zijn darmhormonen die vrijkomen na eten en betrokken zijn bij de regulering van insulineafgifte.","quellen":[{"titel":"NIDDK: Fundamenten van incretineonderzoek","titel_en":"NIDDK: Fundamenten van incretineonderzoek","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"text":"Incretines zijn een hormoonklasse uit de darm die GLP-1 en GIP omvat. Ze worden vrijgegeven uit gespecialiseerde darmcellen na eten en binden hun eigen receptoren op de beta-cellen van het pancreas. Via dit mechanisme is de insulineafgifte na orale glucoseinname hoger dan na een intraveneuze toediening van dezelfde hoeveelheid, een effect bekend als het incretine-effect. Verschillende goedgekeurde en onderzoeksmedicijnen imiteren dit pad.","text_en":"Incretines zijn een hormoonklasse uit de darm die GLP-1 en GIP omvat. Ze worden vrijgegeven uit gespecialiseerde darmcellen na eten en binden hun eigen receptoren op de beta-cellen van het pancreas. Via dit mechanisme is de insulineafgifte na orale glucoseinname hoger dan na een intraveneuze toediening van dezelfde hoeveelheid, een effect bekend als het incretine-effect. Verschillende goedgekeurde en onderzoeksmedicijnen imiteren dit pad.","synonyme":["Incretinehormonen"],"synonyme_en":["Incretinehormonen"],"siehe":["glp-1","gip","peptidhormon","rezeptor"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"ipamorelin","begriff":"Ipamoreline","begriff_en":"Ipamoreline","kategorie":"wirkstoff","kurz":"Synthetisch pentapeptide onderzocht in studies naar de afgifte van groeihormoon.","kurz_en":"Synthetisch pentapeptide onderzocht in studies naar de afgifte van groeihormoon.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 9849822","titel_en":"PubMed: Onderzoekspublicatie, PMID 9849822","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"text":"Het ontwikkelingsdocument beschrijft een pentapeptide en onderzoekt receptorbetrokkenheid en hormoonafgifte in cellulaire en dierlijke modellen. Die bevindingen kunnen niet algemeen naar mensen worden overgeheveld.","text_en":"Het ontwikkelingsdocument beschrijft een pentapeptide en onderzoekt receptorbetrokkenheid en hormoonafgifte in cellulaire en dierlijke modellen. Die bevindingen kunnen niet algemeen naar mensen worden overgeheveld.","synonyme":["NNC 26-0161"],"synonyme_en":["NNC 26-0161"],"link":"wirkstoffe/ipamorelin.html"},{"slug":"iso-17025","begriff":"ISO 17025","begriff_en":"ISO 17025","kategorie":"labor","kurz":"ISO 17025 is de internationale standaard voor de technische bekwaamheid van test- en kalibratielaboratoria.","kurz_en":"ISO 17025 is de internationale standaard voor de technische bekwaamheid van test- en kalibratielaboratoria.","quellen":[{"titel":"ISO/IEC 17025:2017: Bekwaamheid van testlaboratoria","titel_en":"ISO/IEC 17025:2017: Bekwaamheid van testlaboratoria","url":"https://www.iso.org/standard/66912.html"}],"langform":"ISO/IEC 17025","langform_en":"ISO/IEC 17025","text":"Accreditatie onder deze standaard betekent dat de procedures, apparatuur en personeel van een lab onafhankelijk zijn beoordeeld. Het is een kwaliteitsindicator voor het laboratorium zelf, geen garantie voor een specifiek CoA-resultaat.","text_en":"Accreditatie onder deze standaard betekent dat de procedures, apparatuur en personeel van een lab onafhankelijk zijn beoordeeld. Het is een kwaliteitsindicator voor het laboratorium zelf, geen garantie voor een specifiek CoA-resultaat.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"internationale-einheit","begriff":"IE","begriff_en":"IE","kategorie":"handhabung","kurz":"De Internationale Eenheid meet de biologische potentie van een stof ten opzichte van een referentiestandaard, niet zijn gewicht.","kurz_en":"De Internationale Eenheid meet de biologische potentie van een stof ten opzichte van een referentiestandaard, niet zijn gewicht.","quellen":[{"titel":"WHO: biologische referentiestandaarden","titel_en":"WHO: biologische referentiestandaarden","url":"https://www.who.int/activities/providing-international-biological-reference-standards"}],"langform":"Internationale Eenheid","langform_en":"Internationale Eenheid","text":"Bij stoffen zoals groeihormoon zegt het gewicht alleen weinig over de hoeveelheid, omdat verschillende batches bij hetzelfde gewicht in zuiverheid kunnen verschillen. De Internationale Eenheid relateert de hoeveelheid daarom aan een gedefinieerd WHO-referentiepreparaat. Eén milligram van het ene hormoon komt daarom niet automatisch overeen met hetzelfde aantal eenheden als één milligram van een ander preparaat.","text_en":"Bij stoffen zoals groeihormoon zegt het gewicht alleen weinig over de hoeveelheid, omdat verschillende batches bij hetzelfde gewicht in zuiverheid kunnen verschillen. De Internationale Eenheid relateert de hoeveelheid daarom aan een gedefinieerd WHO-referentiepreparaat. Eén milligram van het ene hormoon komt daarom niet automatisch overeen met hetzelfde aantal eenheden als één milligram van een ander preparaat.","synonyme":["IE"],"synonyme_en":["IE"],"siehe":["milligramm-mikrogramm","wachstumshormon"]},{"slug":"kisspeptin","begriff":"Kisspeptine-10","begriff_en":"Kisspeptine-10","kategorie":"wirkstoff","kurz":"Peptidefamilie onderzocht in endocriene onderzoek; dit catalogus richt zich op kisspeptine-10.","kurz_en":"Peptidefamilie onderzocht in endocriene onderzoek; dit catalogus richt zich op kisspeptine-10.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 21632807","titel_en":"PubMed: Onderzoekspublicatie, PMID 21632807","url":"https://pubmed.ncbi.nlm.nih.gov/21632807/"}],"text":"De geciteerde studie onderzoekt kisspeptine-10 bij mannen. Andere isoformen zoals kisspeptine-54 moeten apart overwogen worden. De overkoepelende term kisspeptine specificeert de onderzochte vorm niet volledig.","text_en":"De geciteerde studie onderzoekt kisspeptine-10 bij mannen. Andere isoformen zoals kisspeptine-54 moeten apart overwogen worden. De overkoepelende term kisspeptine specificeert de onderzochte vorm niet volledig.","synonyme":["Metastin (45-54)","KP-10"],"synonyme_en":["Metastin (45-54)","KP-10"],"link":"wirkstoffe/kisspeptin.html"},{"slug":"klinische-studie","begriff":"Klinische proef","begriff_en":"Klinische proef","kategorie":"studien","kurz":"Een studie bij menselijke deelnemers, meestal gestructureerd in fasen I tot III. Het meest informatieve studietype voor mensen.","kurz_en":"Een studie bij menselijke deelnemers, meestal gestructureerd in fasen I tot III. Het meest informatieve studietype voor mensen.","quellen":[{"titel":"NCI: klinische proef","titel_en":"NCI: klinische proef","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/clinical-trial"}],"text":"Een klinische studie onderzoekt een medische vraag die betrekking heeft op mensen. Studies verschillen in grootte, vergelijkingsgroepen, blinding en gemeten uitkomsten. Deze kenmerken helpen bepalen hoe betrouwbaar een resultaat is. Registratie of publicatie van een studie alleen vestigt geen goedkeuring of de kwaliteit van een winkelproduct.","text_en":"Een klinische studie onderzoekt een medische vraag die betrekking heeft op mensen. Studies verschillen in grootte, vergelijkingsgroepen, blinding en gemeten uitkomsten. Deze kenmerken helpen bepalen hoe betrouwbaar een resultaat is. Registratie of publicatie van een studie alleen vestigt geen goedkeuring of de kwaliteit van een winkelproduct.","synonyme":["Klinische studie"],"synonyme_en":["Klinische studie"],"siehe":["studienphasen","rct","placebo","Dubbelblind"],"seiten":["studien.html"]},{"slug":"cohort-study","begriff":"Cohortonderzoek","begriff_en":"Cohortonderzoek","kategorie":"studien","kurz":"Observationele studie die groepen die in één kenmerk verschillen in de loop van de tijd volgt en een uitkomst vergelijkt.","kurz_en":"Observationele studie die groepen die in één kenmerk verschillen in de loop van de tijd volgt en een uitkomst vergelijkt.","quellen":[{"titel":"NCI: cohortonderzoek","titel_en":"NCI: cohortonderzoek","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/cohort-study"}],"text":"Bij cohortonderzoek worden groepen mensen die in één kenmerk verschillen (bijvoorbeeld roken of niet roken) gedurende een periode gevolgd en wordt een bepaalde uitkomst vergeleken. Onderzoekers grijpen niet in. Zulk onderzoek toont associaties, geen oorzaak en gevolg, omdat de groepen ook op andere punten kunnen verschillen.","text_en":"Bij cohortonderzoek worden groepen mensen die in één kenmerk verschillen (bijvoorbeeld roken of niet roken) gedurende een periode gevolgd en wordt een bepaalde uitkomst vergeleken. Onderzoekers grijpen niet in. Zulk onderzoek toont associaties, geen oorzaak en gevolg, omdat de groepen ook op andere punten kunnen verschillen.","synonyme":["Cohortonderzoeken"],"synonyme_en":["Cohortonderzoeken"],"siehe":["observational-study","association","confounder"],"seiten":["studien.html"]},{"slug":"confidence-interval","begriff":"Betrouwbaarheidsinterval","begriff_en":"Betrouwbaarheidsinterval","kategorie":"studien","kurz":"Bereik van waarden dat is opgebouwd om de ware waarde met een bepaalde waarschijnlijkheid te bevatten, meestal 95%.","kurz_en":"Bereik van waarden dat is opgebouwd om de ware waarde met een bepaalde waarschijnlijkheid te bevatten, meestal 95%.","quellen":[{"titel":"NLM MeSH: Confidence Intervals","titel_en":"NLM MeSH: Confidence Intervals","url":"https://www.ncbi.nlm.nih.gov/mesh/68016001"}],"text":"Een betrouwbaarheidsinterval (BI) is een bereik van waarden dat zo is opgebouwd dat het de ware waarde van een grootheid, zoals een percentage of hazard ratio, met een bepaalde waarschijnlijkheid bevat, meestal 95%. Een smal interval wijst op een nauwkeurigere schatting. Als het interval van een hazard ratio de waarde 1 bevat, is een verschil tussen de groepen statistisch niet vastgesteld.","text_en":"Een betrouwbaarheidsinterval (BI) is een bereik van waarden dat zo is opgebouwd dat het de ware waarde van een grootheid, zoals een percentage of hazard ratio, met een bepaalde waarschijnlijkheid bevat, meestal 95%. Een smal interval wijst op een nauwkeurigere schatting. Als het interval van een hazard ratio de waarde 1 bevat, is een verschil tussen de groepen statistisch niet vastgesteld.","synonyme":["BI","Betrouwbaarheidsbereik"],"synonyme_en":["BI","Betrouwbaarheidsbereik"],"siehe":["hazard-ratio","metaanalyse"],"seiten":["studien.html"]},{"slug":"konzentration","begriff":"Concentratie","begriff_en":"Concentratie","kategorie":"handhabung","kurz":"Concentratie geeft aan hoeveel van een stof is opgelost in een bepaalde hoeveelheid vloeistof, meestal in mg per ml.","kurz_en":"Concentratie geeft aan hoeveel van een stof is opgelost in een bepaalde hoeveelheid vloeistof, meestal in mg per ml.","quellen":[{"titel":"IUPAC Gold Book: Massa concentratie","titel_en":"IUPAC Gold Book: Massa concentratie","url":"https://goldbook.iupac.org/terms/view/M03713"}],"text":"Massa concentratie relateert de massa van een gespecificeerde stof aan het eindvolume van de oplossing, bijvoorbeeld in mg/ml. Poedervorm en daadwerkelijke peptide massa kunnen verschillen. Deze waarde beschrijft de samenstelling, niet een toepassing.","text_en":"Massa concentratie relateert de massa van een gespecificeerde stof aan het eindvolume van de oplossing, bijvoorbeeld in mg/ml. Poedervorm en daadwerkelijke peptide massa kunnen verschillen. Deze waarde beschrijft de samenstelling, niet een toepassing.","siehe":["rekonstitution","milligramm-mikrogramm","aliquot"]},{"slug":"kpv","begriff":"KPV","begriff_en":"KPV","kategorie":"wirkstoff","kurz":"Melanocortine-afgeleid tripeptide onderzocht in preklinische ontstekingsmodellen","kurz_en":"Melanocortine-afgeleid tripeptide onderzocht in preklinische ontstekingsmodellen","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 18092346","titel_en":"PubMed: Onderzoekspublicatie, PMID 18092346","url":"https://pubmed.ncbi.nlm.nih.gov/18092346/"}],"text":"KPV staat voor lysine-proline-valine, een kort fragment in de melanocortine context. Het geciteerde artikel onderzoekt het in muizenmodellen van inflammatoire darmziekte. Dit is geen klinisch bewijs van gebruik.","text_en":"KPV staat voor lysine-proline-valine, een kort fragment in de melanocortine context. Het geciteerde artikel onderzoekt het in muizenmodellen van inflammatoire darmziekte. Dit is geen klinisch bewijs van gebruik.","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"synonyme_en":["Lys-Pro-Val","alpha-MSH(11-13)"],"link":"wirkstoffe/kpv.html"},{"slug":"kupferpeptid","begriff":"Koperpeptiden","begriff_en":"Koperpeptiden","kategorie":"klassen","kurz":"Koperpeptiden zijn complexen van een klein peptide en een koperion, het best bekende is GHK-Cu.","kurz_en":"Koperpeptiden zijn complexen van een klein peptide en een koperion, het best bekende is GHK-Cu.","quellen":[{"titel":"GHK als koperbindend peptide in kristallografie","titel_en":"GHK als koperbindend peptide in kristallografie","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7709198/"}],"text":"Koperpeptiden zijn verbindingen waarin een klein peptide een koperion coördineert. Het best bekende voorbeeld is GHK, een drie-aminozuur peptide gevonden in menselijk bloedplasma, speeksel en urine, waar het natuurlijk voorkomt gebonden aan koper. In zijn kopercomplex vorm wordt GHK-Cu voornamelijk bestudeerd in huidonderzoek, met aanvullende preklinische gegevens over bindweefsel en wondgenezing.","text_en":"Koperpeptiden zijn verbindingen waarin een klein peptide een koperion coördineert. Het best bekende voorbeeld is GHK, een drie-aminozuur peptide gevonden in menselijk bloedplasma, speeksel en urine, waar het natuurlijk voorkomt gebonden aan koper. In zijn kopercomplex vorm wordt GHK-Cu voornamelijk bestudeerd in huidonderzoek, met aanvullende preklinische gegevens over bindweefsel en wondgenezing.","synonyme":["GHK-Cu complexen"],"synonyme_en":["GHK-Cu complexen"],"siehe":["aminosaeure","peptid"],"wirkstoffe":["ghk-cu"],"seiten":["peptid-1x1.html"]},{"slug":"lagerung","begriff":"Opslag","begriff_en":"Opslag","kategorie":"handhabung","kurz":"Opslag beschrijft hoe een peptide wordt bewaard voor gebruik, meestal koel, droog en donker afhankelijk van zijn toestand.","kurz_en":"Opslag beschrijft hoe een peptide wordt bewaard voor gebruik, meestal koel, droog en donker afhankelijk van zijn toestand.","quellen":[{"titel":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","titel_en":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Stabiliteit hangt af van sequentie, formulering en omstandigheden, onder andere factoren. De specificatie van het materiaal en de onderbouwde stabiliteitsgegevens zijn doorslaggevend.","text_en":"Stabiliteit hangt af van sequentie, formulering en omstandigheden, onder andere factoren. De specificatie van het materiaal en de onderbouwde stabiliteitsgegevens zijn doorslaggevend.","siehe":["lyophilisat","lichtschutz","rekonstitution"]},{"slug":"lichtschutz","begriff":"Lichtbescherming","begriff_en":"Lichtbescherming","kategorie":"handhabung","kurz":"Lichtbescherming omvat maatregelen die een monster beschermen tegen lichtblootstelling, zoals amberkleurige flesjes of opslag in het donker.","kurz_en":"Lichtbescherming omvat maatregelen die een monster beschermen tegen lichtblootstelling, zoals amberkleurige flesjes of opslag in het donker.","quellen":[{"titel":"ICH Q1B: Fotostabiliteitstesting","titel_en":"ICH Q1B: Fotostabiliteitstesting","url":"https://www.ema.europa.eu/en/scientific-guidelines/ich-q1b-photostability-testing-new-active-substances-medicinal-products"}],"text":"Fotostabiliteitstests onderzoeken of licht een stof of formulering verandert. Geschikte verpakking kan blootstelling beperken. Vereiste omstandigheden zijn productspecifiek; lichtbescherming alleen stelt geen specifieke houdbaarheid vast.","text_en":"Fotostabiliteitstests onderzoeken of licht een stof of formulering verandert. Geschikte verpakking kan blootstelling beperken. Vereiste omstandigheden zijn productspecifiek; lichtbescherming alleen stelt geen specifieke houdbaarheid vast.","siehe":["lagerung","lyophilisat"]},{"slug":"ll-37","begriff":"LL-37","begriff_en":"LL-37","kategorie":"wirkstoff","kurz":"Endogeen antimicrobieel peptide ook onderzocht in klinisch wondonderzoek.","kurz_en":"Endogeen antimicrobieel peptide ook onderzocht in klinisch wondonderzoek.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 25041740","titel_en":"PubMed: Onderzoekspublicatie, PMID 25041740","url":"https://pubmed.ncbi.nlm.nih.gov/25041740/"}],"text":"De gelinkte gerandomiseerde studie onderzoekt LL-37 in moeilijk te genezen veneuze beenulcera. De bevindingen betreffen de specifieke studievoorbereiding en -ontwerp, niet elk product gelabeld LL-37.","text_en":"De gelinkte gerandomiseerde studie onderzoekt LL-37 in moeilijk te genezen veneuze beenulcera. De bevindingen betreffen de specifieke studievoorbereiding en -ontwerp, niet elk product gelabeld LL-37.","synonyme":["Cathelicidin","hCAP18(134-170)","Mens Cathelicidin"],"synonyme_en":["Cathelicidin","hCAP18(134-170)","Mens Cathelicidin"],"link":"wirkstoffe/ll-37.html"},{"slug":"lyophilisat","begriff":"Lyophilisaat","begriff_en":"Lyophilisaat","kategorie":"handhabung","kurz":"Materiaal verkregen door vriesdrogen, zoals een poeder in een laboratoriumvial.","kurz_en":"Materiaal verkregen door vriesdrogen, zoals een poeder in een laboratoriumvial.","quellen":[{"titel":"FDA: Lyofilisatie","titel_en":"FDA: Lyofilisatie","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"Vriesdrogen verwijdert water uit een bevroren monster onder vacuüm. Het laat een droog poeder of poreuze cake achter. Stabiliteit en houdbaarheid hangen af van de stof, de formulering en de verpakking; de fysieke vorm alleen garandeert deze niet.","text_en":"Vriesdrogen verwijdert water uit een bevroren monster onder vacuüm. Het laat een droog poeder of poreuze cake achter. Stabiliteit en houdbaarheid hangen af van de stof, de formulering en de verpakking; de fysieke vorm alleen garandeert deze niet.","siehe":["rekonstitution","lagerung","lichtschutz","charge"]},{"slug":"massenspektrometrie","begriff":"Massaspectrometrie","begriff_en":"Massaspectrometrie","kategorie":"labor","kurz":"Massaspectrometrie bepaalt het molecuulgewicht van een monster en bevestigt zo welke molecuul er daadwerkelijk aanwezig is.","kurz_en":"Massaspectrometrie bepaalt het molecuulgewicht van een monster en bevestigt zo welke molecuul er daadwerkelijk aanwezig is.","quellen":[{"titel":"FDA: Analyse van complexe mengsels en peptiden","titel_en":"FDA: Analyse van complexe mengsels en peptiden","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"In combinatie met vloeistofchromatografie (LC-MS) verifieert het de identiteit van een peptide onafhankelijk van de zuiverheidswaarde. Een hoge zuiverheidswaarde zonder deze controle zegt niets over of het juiste molecuul überhaupt aanwezig is.","text_en":"In combinatie met vloeistofchromatografie (LC-MS) verifieert het de identiteit van een peptide onafhankelijk van de zuiverheidswaarde. Een hoge zuiverheidswaarde zonder deze controle zegt niets over of het juiste molecuul überhaupt aanwezig is.","synonyme":["MS"],"synonyme_en":["MS"],"siehe":["identitaet","hplc","coa"],"seiten":["peptid-1x1.html"]},{"slug":"melanocortin","begriff":"Melanocortine","begriff_en":"Melanocortine","kategorie":"klassen","kurz":"Melanocortine zijn peptidehormonen afgeleid van POMC die vijf receptortypes binden die de huid, eetlust en seksuele respons reguleren.","kurz_en":"Melanocortine zijn peptidehormonen afgeleid van POMC die vijf receptortypes binden die de huid, eetlust en seksuele respons reguleren.","quellen":[{"titel":"NCBI Endotext: Melanocortine receptoren","titel_en":"NCBI Endotext: Melanocortine receptoren","url":"https://www.ncbi.nlm.nih.gov/books/NBK279118/"}],"text":"Melanocortine zijn een familie van peptidehormonen afgeleid van het precursor eiwit proopiomelanocortine (POMC), inclusief alpha-MSH en ACTH. Ze binden vijf verschillende melanocortine receptoren (MC1R tot MC5R) die huidpigmentatie, eetlust, energiebalans, ontstekingsprocessen en seksuele respons, onder andere functies, reguleren. Synthetische melanocortine receptor agonisten richten zich op individuele receptoren binnen dit systeem.","text_en":"Melanocortine zijn een familie van peptidehormonen afgeleid van het precursor eiwit proopiomelanocortine (POMC), inclusief alpha-MSH en ACTH. Ze binden vijf verschillende melanocortine receptoren (MC1R tot MC5R) die huidpigmentatie, eetlust, energiebalans, ontstekingsprocessen en seksuele respons, onder andere functies, reguleren. Synthetische melanocortine receptor agonisten richten zich op individuele receptoren binnen dit systeem.","synonyme":["Melanocortine systeem"],"synonyme_en":["Melanocortine systeem"],"siehe":["rezeptor","agonist","peptidhormon"],"wirkstoffe":["melanotan-2","pt-141"],"seiten":["peptid-1x1.html"]},{"slug":"melanotan-2","begriff":"Melanotan II","begriff_en":"Melanotan II","kategorie":"wirkstoff","kurz":"Synthetisch melanocortine analoog onderzocht in vroege klinische studies.","kurz_en":"Synthetisch melanocortine analoog onderzocht in vroege klinische studies.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 8637402","titel_en":"PubMed: Onderzoekspublicatie, PMID 8637402","url":"https://pubmed.ncbi.nlm.nih.gov/8637402/"}],"text":"Het geciteerde vroege fase I artikel onderzoekt melanotan II in een kleine pilotstudie. Het stelt geen betrouwbare risico-batenbeoordeling voor algemeen gebruik.","text_en":"Het geciteerde vroege fase I artikel onderzoekt melanotan II in een kleine pilotstudie. Het stelt geen betrouwbare risico-batenbeoordeling voor algemeen gebruik.","synonyme":["MT-2","MT2"],"synonyme_en":["MT-2","MT2"],"link":"wirkstoffe/melanotan-2.html"},{"slug":"metaanalyse","begriff":"Meta-analyse","begriff_en":"Meta-analyse","kategorie":"studien","kurz":"Een statistische synthese van meerdere studies die een gemeenschappelijke vraag behandelen.","kurz_en":"Een statistische synthese van meerdere studies die een gemeenschappelijke vraag behandelen.","quellen":[{"titel":"NCI: meta-analyse","titel_en":"NCI: meta-analyse","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/meta-analysis"}],"text":"Een meta-analyse combineert statistisch vergelijkbare resultaten uit meerdere studies. Het kan nauwkeurigere schattingen geven. De sterkte hangt af van de kwaliteit, vergelijkbaarheid en volledigheid van het opgenomen bewijs.","text_en":"Een meta-analyse combineert statistisch vergelijkbare resultaten uit meerdere studies. Het kan nauwkeurigere schattingen geven. De sterkte hangt af van de kwaliteit, vergelijkbaarheid en volledigheid van het opgenomen bewijs.","siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"milligramm-mikrogramm","begriff":"Milligram / microgram","begriff_en":"Milligram / microgram","kategorie":"handhabung","kurz":"Eén milligram is gelijk aan 1000 microgram, de standaard massa-eenheid voor kleine peptidehoeveelheden op labels en CoAs.","kurz_en":"Eén milligram is gelijk aan 1000 microgram, de standaard massa-eenheid voor kleine peptidehoeveelheden op labels en CoAs.","quellen":[{"titel":"BIPM: SI-vooraanduidingen","titel_en":"BIPM: SI-vooraanduidingen","url":"https://www.bipm.org/en/committees/cg/cgpm/11-1960/resolution-12"}],"text":"Milligrammen (mg) en microgrammen (µg) zijn beide subeenheden van de gram en verschillen met een factor van 1000. Vialabels en CoAs vermelden meestal de peptidehoeveelheid in milligrammen, terwijl individuele componentcijfers soms in microgrammen verschijnen. De calculator op deze pagina converteert tussen grammen, milligrammen en microgrammen op een puur wiskundige basis.","text_en":"Milligrammen (mg) en microgrammen (µg) zijn beide subeenheden van de gram en verschillen met een factor van 1000. Vialabels en CoAs vermelden meestal de peptidehoeveelheid in milligrammen, terwijl individuele componentcijfers soms in microgrammen verschijnen. De calculator op deze pagina converteert tussen grammen, milligrammen en microgrammen op een puur wiskundige basis.","siehe":["konzentration","internationale-einheit"],"seiten":["rechner.html"]},{"slug":"mitochondriales-peptid","begriff":"Mitochondriale peptiden","begriff_en":"Mitochondriale peptiden","kategorie":"klassen","kurz":"Mitochondriale peptiden richten zich op cellulaire energieproductie of komen voort uit mitochondriale DNA.","kurz_en":"Mitochondriale peptiden richten zich op cellulaire energieproductie of komen voort uit mitochondriale DNA.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, preklinisch onderzoek","titel_en":"Lee et al. (2015): MOTS-c, preklinisch onderzoek","url":"https://doi.org/10.1016/j.cmet.2015.02.009"},{"titel":"Cho et al. (2007): Mitochondriale doelen in een ratmodel","titel_en":"Cho et al. (2007): Mitochondriale doelen in een ratmodel","url":"https://pubmed.ncbi.nlm.nih.gov/17429296/"}],"text":"Mitochondriale peptiden zijn geen enkele stofklasse in de klassieke zin. De term groepeert peptiden die zich binden aan het binnenste mitochondriale membraan of die zijn gecodeerd door mitochondriale in plaats van nucleair DNA. De tweede groep omvat een kort peptide afgeleid van het mitochondriale 12S rRNA gen, bestudeerd in metabole onderzoek. Een ander voorbeeld bindt cardioline in het binnenmembraan en wordt gebruikt in onderzoek naar cellulaire veroudering en energie metabolisme.","text_en":"Mitochondriale peptiden zijn geen enkele stofklasse in de klassieke zin. De term groepeert peptiden die zich binden aan het binnenste mitochondriale membraan of die zijn gecodeerd door mitochondriale in plaats van nucleair DNA. De tweede groep omvat een kort peptide afgeleid van het mitochondriale 12S rRNA gen, bestudeerd in metabole onderzoek. Een ander voorbeeld bindt cardioline in het binnenmembraan en wordt gebruikt in onderzoek naar cellulaire veroudering en energie metabolisme.","synonyme":["Mitochondriale peptiden"],"synonyme_en":["Mitochondriale peptiden"],"siehe":["praeklinisch","in-vitro"],"wirkstoffe":["mots-c","ss-31"],"seiten":["studien.html"]},{"slug":"mots-c","begriff":"MOTS-c","begriff_en":"MOTS-c","kategorie":"wirkstoff","kurz":"Mitochondriaal DNA-afgeleid peptide onderzocht in preklinische metabole modellen.","kurz_en":"Mitochondriaal DNA-afgeleid peptide onderzocht in preklinische metabole modellen.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, preklinisch onderzoek","titel_en":"Lee et al. (2015): MOTS-c, preklinisch onderzoek","url":"https://doi.org/10.1016/j.cmet.2015.02.009"}],"text":"Het ontdekkingsartikel beschrijft een korte sequentie gecodeerd in mitochondriale DNA en onderzoekt deze in cellulaire en dierlijke modellen. Zijn rol in mitochondriënonderzoek vestigt geen voordeel van een verkocht product.","text_en":"Het ontdekkingsartikel beschrijft een korte sequentie gecodeerd in mitochondriale DNA en onderzoekt deze in cellulaire en dierlijke modellen. Zijn rol in mitochondriënonderzoek vestigt geen voordeel van een verkocht product.","synonyme":["Mitochondriaal Afgeleid Peptide MOTS-c","Mitochondriaal Open Reading Frame van de 12S rRNA Type-c"],"synonyme_en":["Mitochondriaal Afgeleid Peptide MOTS-c","Mitochondriaal Open Reading Frame van de 12S rRNA Type-c"],"link":"wirkstoffe/mots-c.html"},{"slug":"neuropeptid","begriff":"Neuropeptide","begriff_en":"Neuropeptide","kategorie":"grundlagen","kurz":"Een peptide dat als signaalmolecuul fungeert tussen cellen in het zenuwstelsel.","kurz_en":"Een peptide dat als signaalmolecuul fungeert tussen cellen in het zenuwstelsel.","quellen":[{"titel":"Purves et al.: Peptideneurotransmitters","titel_en":"Purves et al.: Peptideneurotransmitters","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Neuropeptiden zijn peptiden die door zenuwcellen worden vrijgegeven en die als signaalmoleculen binnen het zenuwstelsel werken. Ze verschillen van klassieke neurotransmitters door hun grotere moleculaire structuur en binden ook aan specifieke receptoren op doelcellen. In onderzoek worden neuropeptiden onder andere gebruikt om signaalroutes in het centrale zenuwstelsel te mappen.","text_en":"Neuropeptiden zijn peptiden die door zenuwcellen worden vrijgegeven en die als signaalmoleculen binnen het zenuwstelsel werken. Ze verschillen van klassieke neurotransmitters door hun grotere moleculaire structuur en binden ook aan specifieke receptoren op doelcellen. In onderzoek worden neuropeptiden onder andere gebruikt om signaalroutes in het centrale zenuwstelsel te mappen.","siehe":["peptid","peptidhormon","rezeptor"]},{"slug":"nootropikum","begriff":"Nootropica","begriff_en":"Nootropica","kategorie":"klassen","kurz":"Nootropica zijn een brede stofklasse die wordt bestudeerd in relatie tot geheugen, leren of stressverwerking.","kurz_en":"Nootropica zijn een brede stofklasse die wordt bestudeerd in relatie tot geheugen, leren of stressverwerking.","quellen":[{"titel":"Giurgea (1972): Oorsprong van het nootropisch concept","titel_en":"Giurgea (1972): Oorsprong van het nootropisch concept","url":"https://pubmed.ncbi.nlm.nih.gov/4541214/"}],"text":"De term, in 1972 bedacht door Giurgea, beschrijft stoffen die worden onderzocht in verband met cognitieve functies. Het label alleen toont noch een voordeel noch veiligheid aan. Verschillende stoffen en studieopzetten vragen om een afzonderlijke beoordeling.","text_en":"De term, in 1972 bedacht door Giurgea, beschrijft stoffen die worden onderzocht in verband met cognitieve functies. Het label alleen toont noch een voordeel noch veiligheid aan. Verschillende stoffen en studieopzetten vragen om een afzonderlijke beoordeling.","synonyme":["Slimme Medicijnen"],"synonyme_en":["Slimme Medicijnen"],"siehe":["neuropeptid","rezeptor"],"wirkstoffe":["semax","selank","dihexa"],"seiten":["peptid-1x1.html"]},{"slug":"oligopeptid","begriff":"Oligopeptide","begriff_en":"Oligopeptide","kategorie":"grundlagen","kurz":"Een korte aminozuurketen, geclassificeerd op lengte als di-, tri- of oligopeptide.","kurz_en":"Een korte aminozuurketen, geclassificeerd op lengte als di-, tri- of oligopeptide.","quellen":[{"titel":"Alberts et al.: Proteïnestructuur","titel_en":"Alberts et al.: Proteïnestructuur","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"langform":"Di-, tri- en oligopeptide","langform_en":"Di-, tri- en oligopeptide","text":"Oligopeptiden bevatten een klein aantal aminozuren. Twee vormen een dipeptide en drie een tripeptide. De grens met langere polypeptiden is een benamingconventie, geen afzonderlijke verandering in moleculair type.","text_en":"Oligopeptiden bevatten een klein aantal aminozuren. Twee vormen een dipeptide en drie een tripeptide. De grens met langere polypeptiden is een benamingconventie, geen afzonderlijke verandering in moleculair type.","synonyme":["Dipeptide","Tripeptide"],"synonyme_en":["Dipeptide","Tripeptide"],"siehe":["peptid","aminosaeure","protein"],"seiten":["peptid-1x1.html"]},{"slug":"oxytocin","begriff":"Oxytocine","begriff_en":"Oxytocine","kategorie":"wirkstoff","kurz":"Endogene peptidehormoon ook onderzocht in studies van sociaal gedrag.","kurz_en":"Endogene peptidehormoon ook onderzocht in studies van sociaal gedrag.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 15931222","titel_en":"PubMed: Onderzoekspublicatie, PMID 15931222","url":"https://pubmed.ncbi.nlm.nih.gov/15931222/"}],"text":"De gelinkte gedragsstudie onderzoekt beslissingen in een experimenteel vertrouwenspel. Dergelijke bevindingen vestigen noch algemeen verbeterde sociale relaties noch de veiligheid van vrij verhandelde producten.","text_en":"De gelinkte gedragsstudie onderzoekt beslissingen in een experimenteel vertrouwenspel. Dergelijke bevindingen vestigen noch algemeen verbeterde sociale relaties noch de veiligheid van vrij verhandelde producten.","synonyme":["OXT","Pitocin"],"synonyme_en":["OXT","Pitocin"],"link":"wirkstoffe/oxytocin.html"},{"slug":"partnercode","begriff":"Partnercode","begriff_en":"Partnercode","kategorie":"vergleich","kurz":"Een code die is gekoppeld aan een affiliateprogramma, onderworpen aan de voorwaarden van de leverancier.","kurz_en":"Een code die is gekoppeld aan een affiliateprogramma, onderworpen aan de voorwaarden van de leverancier.","quellen":[{"titel":"Peptide Compass: Onze affiliateverklaring","titel_en":"Peptide Compass: Onze affiliateverklaring","url":"https://peptidkompass.com/nl/affiliate-hinweis.html"}],"text":"Een partnercode is gekoppeld aan een affiliateprogramma. Of deze een korting of commissie genereert, hangt af van de toepasselijke voorwaarden. Momenteel gedocumenteerde partnerschappen en codes staan vermeld in onze affiliateverklaring; ze veranderen de documentatiescore niet.","text_en":"Een partnercode is gekoppeld aan een affiliateprogramma. Of deze een korting of commissie genereert, hangt af van de toepasselijke voorwaarden. Momenteel gedocumenteerde partnerschappen en codes staan vermeld in onze affiliateverklaring; ze veranderen de documentatiescore niet.","siehe":["affiliate-link"],"seiten":["affiliate-hinweis.html","deals.html"]},{"slug":"peer-review","begriff":"Collegiale toetsing (peer review)","begriff_en":"Collegiale toetsing (peer review)","kategorie":"studien","kurz":"Expertbeoordeling van een manuscript van een studie door onafhankelijke specialisten vóór publicatie.","kurz_en":"Expertbeoordeling van een manuscript van een studie door onafhankelijke specialisten vóór publicatie.","quellen":[{"titel":"NIH: Richtlijnen voor wetenschappelijke peer review","titel_en":"NIH: Richtlijnen voor wetenschappelijke peer review","url":"https://oir.nih.gov/system/files/media/file/2026-01/guidelines-conduct_research.pdf"}],"text":"In peer review controleren onafhankelijke experts de methodologie, data-analyse en conclusies van een manuscript vóór publicatie. Zij kunnen correcties aanvragen of het werk afwijzen. Een peer-reviewed publicatie wordt als betrouwbaarder beschouwd dan een niet beoordeerd tekst, hoewel het geen garantie is tegen fouten.","text_en":"In peer review controleren onafhankelijke experts de methodologie, data-analyse en conclusies van een manuscript vóór publicatie. Zij kunnen correcties aanvragen of het werk afwijzen. Een peer-reviewed publicatie wordt als betrouwbaarder beschouwd dan een niet beoordeerd tekst, hoewel het geen garantie is tegen fouten.","siehe":["preprint","pubmed"],"seiten":["studien.html"]},{"slug":"pentadeca-arginate","begriff":"Pentadeca Arginate (PDA)","begriff_en":"Pentadeca Arginate","kategorie":"wirkstoff","kurz":"Handelsbenaming voor een vorm die wordt gepromoot als een argininezout van BPC-157.","kurz_en":"Handelsbenaming voor een vorm die wordt gepromoot als een argininezout van BPC-157.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 27847966","titel_en":"PubMed: Onderzoekspublicatie, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"De geciteerde oorspronkelijke studie onderzoekt BPC-157. Het vestigt geen speciale eigenschappen van een zoutvorm die wordt verkocht als Pentadeca Arginate. Een betrouwbare, toegewijde bron die een superieure oplosbaarheid of stabiliteit van deze gepromote vorm aantoont, is hier niet vastgesteld.","text_en":"De geciteerde oorspronkelijke studie onderzoekt BPC-157. Het vestigt geen speciale eigenschappen van een zoutvorm die wordt verkocht als Pentadeca Arginate. Een betrouwbare, toegewijde bron die een superieure oplosbaarheid of stabiliteit van deze gepromote vorm aantoont, is hier niet vastgesteld.","synonyme":["PDA","BPC-157 arginaatzout"],"synonyme_en":["PDA","BPC-157 arginaatzout"],"link":"wirkstoffe/pentadeca-arginate.html"},{"slug":"peptid","begriff":"Peptide","begriff_en":"Peptiden","kategorie":"grundlagen","kurz":"Een korte keten van aminozuren verbonden door peptidebindingen.","kurz_en":"Een korte keten van aminozuren verbonden door peptidebindingen.","quellen":[{"titel":"NCI: peptide","titel_en":"NCI: peptide","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/peptide"}],"text":"Twee verbonden aminozuren vormen een dipeptide; drie vormen een tripeptide. Langere ketens worden ook polypeptide genoemd. Een vaste grens van 50 aminozuren onderscheidt peptiden van eiwitten in elk veld niet.","text_en":"Twee verbonden aminozuren vormen een dipeptide; drie vormen een tripeptide. Langere ketens worden ook polypeptide genoemd. Een vaste grens van 50 aminozuren onderscheidt peptiden van eiwitten in elk veld niet.","synonyme":["Peptiden"],"synonyme_en":["Peptiden"],"siehe":["aminosaeure","peptidbindung","oligopeptid","protein"],"seiten":["peptid-1x1.html"]},{"slug":"peptidbindung","begriff":"Peptidebinding","begriff_en":"Peptidebinding","kategorie":"grundlagen","kurz":"De chemische verbinding die twee aminozuren in een keten verbindt.","kurz_en":"De chemische verbinding die twee aminozuren in een keten verbindt.","quellen":[{"titel":"Alberts et al.: Proteïnestructuur","titel_en":"Alberts et al.: Proteïnestructuur","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"Een peptidebinding vormt wanneer de carboxylgroep van een aminozuur reageert met de aminogroep van het volgende, waarbij een watermolecuul vrijkomt in het proces. Deze binding herhaalt zich langs de gehele keten en vormt de ruggengraat van peptiden en eiwitten. De volgorde van de aminozuren die op deze manier worden verbonden bepaalt de sequentie.","text_en":"Een peptidebinding vormt wanneer de carboxylgroep van een aminozuur reageert met de aminogroep van het volgende, waarbij een watermolecuul vrijkomt in het proces. Deze binding herhaalt zich langs de gehele keten en vormt de ruggengraat van peptiden en eiwitten. De volgorde van de aminozuren die op deze manier worden verbonden bepaalt de sequentie.","siehe":["aminosaeure","peptid","sequenz"]},{"slug":"peptidgehalt","begriff":"Net Peptide Inhoud","begriff_en":"Net Peptide Inhoud","kategorie":"labor","kurz":"Net peptide inhoud geeft aan welk deel van de massa van een poeder daadwerkelijk het peptide zelf is.","kurz_en":"Net peptide inhoud geeft aan welk deel van de massa van een poeder daadwerkelijk het peptide zelf is.","quellen":[{"titel":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","titel_en":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Peptide inhoud is de daadwerkelijke peptidefractie van een monster. Water en andere bestanddelen kunnen de poedermassa verschillend maken van de peptide massa.","text_en":"Peptide inhoud is de daadwerkelijke peptidefractie van een monster. Water en andere bestanddelen kunnen de poedermassa verschillend maken van de peptide massa.","siehe":["reinheit","gegenion","coa"],"seiten":["methodik.html"]},{"slug":"peptidhormon","begriff":"Peptide hormoon","begriff_en":"Peptide hormoon","kategorie":"grundlagen","kurz":"Een hormoon dat het lichaam produceert dat chemisch een aminozuurketen is.","kurz_en":"Een hormoon dat het lichaam produceert dat chemisch een aminozuurketen is.","quellen":[{"titel":"Purves et al.: Peptideneurotransmitters","titel_en":"Purves et al.: Peptideneurotransmitters","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Een peptidehormoon is een signaalmolecuul opgebouwd uit een keten aminozuren, in tegenstelling tot steroïde hormonen, die gebaseerd zijn op cholesterol. Peptidehormonen worden geproduceerd in klieren of gespecialiseerde cellen en binden aan receptoren op doelcellen. Insuline is een bekend voorbeeld van een endogeen peptidehormoon.","text_en":"Een peptidehormoon is een signaalmolecuul opgebouwd uit een keten aminozuren, in tegenstelling tot steroïde hormonen, die gebaseerd zijn op cholesterol. Peptidehormonen worden geproduceerd in klieren of gespecialiseerde cellen en binden aan receptoren op doelcellen. Insuline is een bekend voorbeeld van een endogeen peptidehormoon.","siehe":["peptid","rezeptor","neuropeptid"]},{"slug":"placebo","begriff":"Placebo","begriff_en":"Placebo","kategorie":"studien","kurz":"Een valse preparatie zonder actief ingrediënt, gebruikt om te vergelijken met een werkelijke stof in een proef. Scheidt echt van verwachte effecten.","kurz_en":"Een valse preparatie zonder actief ingrediënt, gebruikt om te vergelijken met een werkelijke stof in een proef. Scheidt echt van verwachte effecten.","quellen":[{"titel":"NCI: placebo","titel_en":"NCI: placebo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/placebo"}],"text":"Een placebo ziet eruit als de geteste preparatie maar bevat geen actief ingrediënt. In een studieontwerp dient het als de vergelijkingsgroep, om te laten zien hoeveel van een reactie voortkomt uit de verwachting van de deelnemer in plaats van uit de stof zelf. Placebo controle is een kernkenmerk van informatieve klinische proeven, vaak gecombineerd met blinding.","text_en":"Een placebo ziet eruit als de geteste preparatie maar bevat geen actief ingrediënt. In een studieontwerp dient het als de vergelijkingsgroep, om te laten zien hoeveel van een reactie voortkomt uit de verwachting van de deelnemer in plaats van uit de stof zelf. Placebo controle is een kernkenmerk van informatieve klinische proeven, vaak gecombineerd met blinding.","synonyme":["Inactieve preparatie"],"synonyme_en":["Inactieve preparatie"],"siehe":["rct","Dubbelblind"],"seiten":["studien.html"]},{"slug":"praeklinisch","begriff":"Preklinisch","begriff_en":"Preklinisch","kategorie":"studien","kurz":"Het onderzoeksstadium vóór enig menselijk gebruik: celkweek en diermodel. Klinische proeven volgen alleen na dit stadium.","kurz_en":"Het onderzoeksstadium vóór enig menselijk gebruik: celkweek en diermodel. Klinische proeven volgen alleen na dit stadium.","quellen":[{"titel":"NCI: preklinisch onderzoek","titel_en":"NCI: preklinisch onderzoek","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/preclinical-study"}],"text":"Preklinisch onderzoek omvat in vitro en in vivo experimenten die vroege effecten en veiligheid controleren voordat een stof ooit in mensen wordt getest. Het biedt de gegevensbasis voor een mogelijke latere klinische proef. Een preklinisch resultaat ondersteunt alleen geen bewering over mensen.","text_en":"Preklinisch onderzoek omvat in vitro en in vivo experimenten die vroege effecten en veiligheid controleren voordat een stof ooit in mensen wordt getest. Het biedt de gegevensbasis voor een mogelijke latere klinische proef. Een preklinisch resultaat ondersteunt alleen geen bewering over mensen.","synonyme":["Preklinisch onderzoek"],"synonyme_en":["Preklinisch onderzoek"],"siehe":["in-vitro","in-vivo","tiermodell","klinische-studie"],"seiten":["studien.html"]},{"slug":"preis-pro-mg","begriff":"Prijs per milligram","begriff_en":"Prijs per milligram","kategorie":"vergleich","kurz":"Prijs per milligram maakt aanbiedingen met verschillende verpakkingsgroottes direct vergelijkbaar.","kurz_en":"Prijs per milligram maakt aanbiedingen met verschillende verpakkingsgroottes direct vergelijkbaar.","quellen":[{"titel":"Peptide Compass: Onze vergelijkingsmethodologie","titel_en":"Peptide Compass: Onze vergelijkingsmethodologie","url":"https://peptidkompass.com/nl/methodik.html"}],"text":"Het getal is de lijstprijs gedeeld door de milligram inhoud van een product, vergeleken voor dezelfde actieve stof en valuta. Verzending, beschikbaarheid en kortingvoorwaarden worden alleen opgenomen wanneer expliciet gedocumenteerd. Een lager getal zegt niets over zuiverheid of documentatie.","text_en":"Het getal is de lijstprijs gedeeld door de milligram inhoud van een product, vergeleken voor dezelfde actieve stof en valuta. Verzending, beschikbaarheid en kortingvoorwaarden worden alleen opgenomen wanneer expliciet gedocumenteerd. Een lager getal zegt niets over zuiverheid of documentatie.","siehe":["dokumentationsscore"],"seiten":["vergleich.html","rechner.html"]},{"slug":"preprint","begriff":"Preprint","begriff_en":"Preprint","kategorie":"studien","kurz":"Een manuscript dat vóór peer review is gepubliceerd. Resultaten worden beschouwd als voorlopig, nog niet onafhankelijk gecontroleerd.","kurz_en":"Een manuscript dat vóór peer review is gepubliceerd. Resultaten worden beschouwd als voorlopig, nog niet onafhankelijk gecontroleerd.","quellen":[{"titel":"NLM: Beperkingen van PubMed en preprints","titel_en":"NLM: Beperkingen van PubMed en preprints","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"Een preprint wordt gepubliceerd op een open platform voordat een tijdschrift het heeft beoordeeld. Dit versnelt de uitwisseling van resultaten maar betekent dat de methodologie en conclusies nog niet onafhankelijk zijn gecontroleerd. Inhoud uit een preprint moet voorzichtiger worden beoordeeld dan een peer-reviewed publicatie.","text_en":"Een preprint wordt gepubliceerd op een open platform voordat een tijdschrift het heeft beoordeeld. Dit versnelt de uitwisseling van resultaten maar betekent dat de methodologie en conclusies nog niet onafhankelijk zijn gecontroleerd. Inhoud uit een preprint moet voorzichtiger worden beoordeeld dan een peer-reviewed publicatie.","siehe":["peer-review","pubmed"],"seiten":["studien.html"]},{"slug":"protein","begriff":"Eiwit","begriff_en":"Eiwit","kategorie":"grundlagen","kurz":"Een molecuul gemaakt van aminozuurketens met diverse biologische rollen.","kurz_en":"Een molecuul gemaakt van aminozuurketens met diverse biologische rollen.","quellen":[{"titel":"NCI: eiwit","titel_en":"NCI: eiwit","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/protein"}],"text":"Eiwitten bestaan uit één of meer aminozuurketens. Hun sequentie en ruimtelijke structuur bepalen hun eigenschappen. Een vaste ketenlengte definieert alleen niet het onderscheid met peptiden.","text_en":"Eiwitten bestaan uit één of meer aminozuurketens. Hun sequentie en ruimtelijke structuur bepalen hun eigenschappen. Een vaste ketenlengte definieert alleen niet het onderscheid met peptiden.","synonyme":["Eiwit"],"synonyme_en":["Eiwit"],"siehe":["peptid","aminosaeure","oligopeptid"],"seiten":["peptid-1x1.html"]},{"slug":"proteolyse","begriff":"Proteolyse","begriff_en":"Proteolyse","kategorie":"grundlagen","kurz":"De enzymatische afbraak van een aminozuurketen in kleinere fragmenten.","kurz_en":"De enzymatische afbraak van een aminozuurketen in kleinere fragmenten.","quellen":[{"titel":"Alberts et al.: Eiwitsynthese en afbraak","titel_en":"Alberts et al.: Eiwitsynthese en afbraak","url":"https://www.ncbi.nlm.nih.gov/books/NBK26829/"}],"text":"Proteolyse is het proces waarbij enzymen genaamd proteasen de peptidebindingen in een aminozuurketen doorsnijden, waardoor deze in kleinere fragmenten wordt gebroken. Deze afbraak vindt continu in het lichaam plaats en beïnvloedt hoe lang een peptide intact blijft, anders gezegd zijn halfwaardetijd. Studies rapporteren vaak proteolytische stabiliteit als een maat voor de duurzaamheid van een peptide.","text_en":"Proteolyse is het proces waarbij enzymen genaamd proteasen de peptidebindingen in een aminozuurketen doorsnijden, waardoor deze in kleinere fragmenten wordt gebroken. Deze afbraak vindt continu in het lichaam plaats en beïnvloedt hoe lang een peptide intact blijft, anders gezegd zijn halfwaardetijd. Studies rapporteren vaak proteolytische stabiliteit als een maat voor de duurzaamheid van een peptide.","siehe":["halbwertszeit","peptidbindung","bioverfuegbarkeit"]},{"slug":"pt-141","begriff":"PT-141 (bremelanotide)","begriff_en":"PT-141 (bremelanotide)","kategorie":"wirkstoff","kurz":"Bremelanotide, een synthetische melanocortine receptor agonist onderzocht in klinische proeven.","kurz_en":"Bremelanotide, een synthetische melanocortine receptor agonist onderzocht in klinische proeven.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 31599840","titel_en":"PubMed: Onderzoekspublicatie, PMID 31599840","url":"https://pubmed.ncbi.nlm.nih.gov/31599840/"}],"text":"PT-141 is een andere naam voor bremelanotide. De gelinkte publicatie beschrijft twee gerandomiseerde fase III proeven in een gedefinieerde patiëntengroep. Een door een winkel verkocht onderzoeksproduct is niet equivalent aan de studievoorbereiding.","text_en":"PT-141 is een andere naam voor bremelanotide. De gelinkte publicatie beschrijft twee gerandomiseerde fase III proeven in een gedefinieerde patiëntengroep. Een door een winkel verkocht onderzoeksproduct is niet equivalent aan de studievoorbereiding.","synonyme":["Bremelanotide","Vyleesi"],"synonyme_en":["Bremelanotide","Vyleesi"],"link":"wirkstoffe/pt-141.html"},{"slug":"pubmed","begriff":"PubMed","begriff_en":"PubMed","kategorie":"studien","kurz":"Een gratis database die wordt beheerd door de US National Library of Medicine voor biomedische literatuur.","kurz_en":"Een gratis database die wordt beheerd door de US National Library of Medicine voor biomedische literatuur.","quellen":[{"titel":"NLM: Beperkingen van PubMed en preprints","titel_en":"NLM: Beperkingen van PubMed en preprints","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"PubMed indexeert miljoenen artikelen uit de geneeskunde en de levenswetenschappen en toont meestal direct een gratis abstract. De volledige tekst bevindt zich vaak achter de paywall van het betreffende tijdschrift. Een PubMed vermelding bevestigt dat een paper is geïndexeerd, maar zegt niets over de kwaliteit van dat individuele onderzoek.","text_en":"PubMed indexeert miljoenen artikelen uit de geneeskunde en de levenswetenschappen en toont meestal direct een gratis abstract. De volledige tekst bevindt zich vaak achter de paywall van het betreffende tijdschrift. Een PubMed vermelding bevestigt dat een paper is geïndexeerd, maar zegt niets over de kwaliteit van dat individuele onderzoek.","siehe":["peer-review","preprint"],"seiten":["studien.html"]},{"slug":"rct","begriff":"RCT","begriff_en":"RCT","kategorie":"studien","kurz":"Een studieopzet met willekeurige toewijzing aan een behandelgroep en een controlegroep. Beschouwd als de gouden standaard voor het bewijzen van een effect.","kurz_en":"Een studieopzet met willekeurige toewijzing aan een behandelgroep en een controlegroep. Beschouwd als de gouden standaard voor het bewijzen van een effect.","quellen":[{"titel":"NCI: Willekeurige klinische proeven","titel_en":"NCI: Willekeurige klinische proeven","url":"https://www.cancer.gov/publications/patient-education/crs.pdf"}],"langform":"Willekeurige gecontroleerde proef","langform_en":"Willekeurige gecontroleerde proef","text":"In een willekeurig gecontroleerde proef worden deelnemers willekeurig toegewezen aan een behandelgroep of een controlegroep, vaak ook verblind. Dit vermindert bias door verwachting of selectie. RCT's worden beschouwd als de methodologische gouden standaard in klinisch onderzoek, vooral gecombineerd met placebo controle.","text_en":"In een willekeurig gecontroleerde proef worden deelnemers willekeurig toegewezen aan een behandelgroep of een controlegroep, vaak ook verblind. Dit vermindert bias door verwachting of selectie. RCT's worden beschouwd als de methodologische gouden standaard in klinisch onderzoek, vooral gecombineerd met placebo controle.","siehe":["placebo","Dubbelblind","klinische-studie"],"seiten":["studien.html"]},{"slug":"reinheit","begriff":"Zuiverheid","begriff_en":"Zuiverheid","kategorie":"labor","kurz":"Zuiverheid geeft aan hoeveel van het chromatogrampiekgebied van een monster behoort tot het hoofdmolecuul, meestal als percentage van HPLC.","kurz_en":"Zuiverheid geeft aan hoeveel van het chromatogrampiekgebied van een monster behoort tot het hoofdmolecuul, meestal als percentage van HPLC.","quellen":[{"titel":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","titel_en":"Hoofnagle et al. (2016): Peptide analyse en laboratoriumbehandeling","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Zuiverheid beschrijft het aandeel van de doelsubstantie binnen een gespecificeerde methode. Een HPLC areapercentage stelt de samenstelling niet volledig vast.","text_en":"Zuiverheid beschrijft het aandeel van de doelsubstantie binnen een gespecificeerde methode. Een HPLC areapercentage stelt de samenstelling niet volledig vast.","siehe":["hplc","identitaet","peptidgehalt"],"seiten":["peptid-1x1.html"]},{"slug":"rekonstitution","begriff":"Reconstitutie","begriff_en":"Reconstitutie","kategorie":"handhabung","kurz":"Reconstitutie is het oplossen van een gevriesdroogd peptide in een vloeistof om een oplossing voor laboratoriumgebruik voor te bereiden.","kurz_en":"Reconstitutie is het oplossen van een gevriesdroogd peptide in een vloeistof om een oplossing voor laboratoriumgebruik voor te bereiden.","quellen":[{"titel":"FDA: Lyofilisatie","titel_en":"FDA: Lyofilisatie","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"De term betekent het herstellen van een vloeibare vorm uit een droge preparatie. De geschikte vloeistof hangt af van de substantie en het analytische procedure. De term impliceert geen algemene preparatie of toedieningsmethode.","text_en":"De term betekent het herstellen van een vloeibare vorm uit een droge preparatie. De geschikte vloeistof hangt af van de substantie en het analytische procedure. De term impliceert geen algemene preparatie of toedieningsmethode.","siehe":["lyophilisat","bakteriostatisches-wasser","steriles-wasser","konzentration"],"seiten":["rechner.html"]},{"slug":"retatrutid","begriff":"Retatrutide","begriff_en":"Retatrutide","kategorie":"wirkstoff","kurz":"Peptide triple-receptor agonist onderzocht in klinische proeven.","kurz_en":"Peptide triple-receptor agonist onderzocht in klinische proeven.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 37366315","titel_en":"PubMed: Onderzoekspublicatie, PMID 37366315","url":"https://pubmed.ncbi.nlm.nih.gov/37366315/"}],"text":"De gelinkte fase II proef onderzoekt een agonist op GIP, GLP-1 en glucagonreceptoren. Resultaten uit die proef stellen geen equivalentie van een commercieel product vast verkocht onder dezelfde naam.","text_en":"De gelinkte fase II proef onderzoekt een agonist op GIP, GLP-1 en glucagonreceptoren. Resultaten uit die proef stellen geen equivalentie van een commercieel product vast verkocht onder dezelfde naam.","synonyme":["LY3437943"],"synonyme_en":["LY3437943"],"link":"wirkstoffe/retatrutid.html"},{"slug":"rezeptor","begriff":"Receptor","begriff_en":"Receptor","kategorie":"grundlagen","kurz":"Een eiwit op of binnen een cel waar een peptide specifiek aan bindt.","kurz_en":"Een eiwit op of binnen een cel waar een peptide specifiek aan bindt.","quellen":[{"titel":"NCI: receptor","titel_en":"NCI: receptor","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/receptor"}],"text":"Een receptor is een eiwit dat een overeenkomstige molecuul, zoals een peptide, specifiek herkent en bindt, vergelijkbaar met een slot en een sleutel. Deze binding activeert een signaalcascade binnen de cel. In onderzoek wordt hoe sterk een peptide bindt aan een gegeven receptor aangeduid als affiniteit en wordt dit vaak in het lab bestudeerd met celculturen.","text_en":"Een receptor is een eiwit dat een overeenkomstige molecuul, zoals een peptide, specifiek herkent en bindt, vergelijkbaar met een slot en een sleutel. Deze binding activeert een signaalcascade binnen de cel. In onderzoek wordt hoe sterk een peptide bindt aan een gegeven receptor aangeduid als affiniteit en wordt dit vaak in het lab bestudeerd met celculturen.","siehe":["agonist","peptidhormon","neuropeptid"]},{"slug":"rezeptpflicht","begriff":"Receptplicht","begriff_en":"Receptplicht","kategorie":"recht","kurz":"Receptplicht betekent dat een geneesmiddel alleen op recept van een arts mag worden afgeleverd.","kurz_en":"Receptplicht betekent dat een geneesmiddel alleen op recept van een arts mag worden afgeleverd.","quellen":[{"titel":"Duitse Geneesmiddelenwet, § 48: Receptplicht","titel_en":"Duitse Geneesmiddelenwet, § 48: Receptplicht","url":"https://www.gesetze-im-internet.de/amg_1976/__48.html"}],"text":"In Duitsland zijn § 48 van de Geneesmiddelenwet en de verordening voor receptplichtige geneesmiddelen bijzonder relevant. Receptplicht, status als geneesmiddel en vergunning zijn afzonderlijke vragen. Verkoop als onderzoekschemicalie levert geen algemene vrijstelling op.","text_en":"In Duitsland zijn § 48 van de Geneesmiddelenwet en de verordening voor receptplichtige geneesmiddelen bijzonder relevant. Receptplicht, status als geneesmiddel en vergunning zijn afzonderlijke vragen. Verkoop als onderzoekschemicalie levert geen algemene vrijstelling op.","siehe":["arzneimittel","zulassung"],"seiten":["peptid-1x1.html"]},{"slug":"ruo","begriff":"RUO","begriff_en":"RUO","kategorie":"recht","kurz":"Research Use Only beschrijft een onderzoeksdoel. De afkorting alleen legt de wettelijke status van een product niet vast.","kurz_en":"Research Use Only beschrijft een onderzoeksdoel. De afkorting alleen legt de wettelijke status van een product niet vast.","quellen":[{"titel":"Duitse Geneesmiddelenwet, § 2: Definitie van geneesmiddelen","titel_en":"Duitse Geneesmiddelenwet, § 2: Definitie van geneesmiddelen","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"},{"titel":"FDA (24 augustus 2026): RUO labeling en beoogd gebruik, USA","titel_en":"FDA (24 augustus 2026): RUO labeling en beoogd gebruik, USA","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/warning-letters/txp-innovations-llc-dba-tex-peptides-735067-08242026"}],"langform":"Research Use Only (alleen voor onderzoeksgebruik)","langform_en":"Research Use Only (alleen voor onderzoeksgebruik)","text":"Het label beschrijft het door de leverancier opgegeven beoogde doel. Het is geen vergunning en ook geen bewijs van zuiverheid of veiligheid. Of een product juridisch als geneesmiddel kwalificeert, hangt af van wettelijke criteria en de feitelijke presentatie, niet uitsluitend van deze afkorting.","text_en":"Het label beschrijft het door de leverancier opgegeven beoogde doel. Het is geen vergunning en ook geen bewijs van zuiverheid of veiligheid. Of een product juridisch als geneesmiddel kwalificeert, hangt af van wettelijke criteria en de feitelijke presentatie, niet uitsluitend van deze afkorting.","siehe":["arzneimittel","zulassung"],"seiten":["methodik.html"]},{"slug":"selank","begriff":"Selank","begriff_en":"Selank","kategorie":"wirkstoff","kurz":"Synthetisch peptide onderzocht in studies naar angststoornissen.","kurz_en":"Synthetisch peptide onderzocht in studies naar angststoornissen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 18454096","titel_en":"PubMed: Onderzoekspublicatie, PMID 18454096","url":"https://pubmed.ncbi.nlm.nih.gov/18454096/"}],"text":"Het gelinkte klinische artikel vergelijkt selank met medazepam bij angststoornissen en neurasthenie. Een enkele publicatie vervangt noch een omvattende bewijsvoering noch de kwaliteitsverificatie van gemaakte producten.","text_en":"Het gelinkte klinische artikel vergelijkt selank met medazepam bij angststoornissen en neurasthenie. Een enkele publicatie vervangt noch een omvattende bewijsvoering noch de kwaliteitsverificatie van gemaakte producten.","link":"wirkstoffe/selank.html"},{"slug":"semaglutid","begriff":"Semaglutide","begriff_en":"Semaglutide","kategorie":"wirkstoff","kurz":"GLP-1 analoog met klinisch onderzoek en geautoriseerde geneesmiddelen.","kurz_en":"GLP-1 analoog met klinisch onderzoek en geautoriseerde geneesmiddelen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 33567185","titel_en":"PubMed: Onderzoekspublicatie, PMID 33567185","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/"},{"titel":"EMA: Productspecifieke autorisatie van Ozempic","titel_en":"EMA: Productspecifieke autorisatie van Ozempic","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Het gelinkte klinische artikel onderzoekt semaglutide bij volwassenen met overgewicht of obesitas. De EMA-beoordeling betreft het specifieke geneesmiddel Ozempic. Noch de studie noch de autorisatie verifieert een vergelijkbaar benoemd onderzoekslaboratoriumproduct.","text_en":"Het gelinkte klinische artikel onderzoekt semaglutide bij volwassenen met overgewicht of obesitas. De EMA-beoordeling betreft het specifieke geneesmiddel Ozempic. Noch de studie noch de autorisatie verifieert een vergelijkbaar benoemd onderzoekslaboratoriumproduct.","link":"wirkstoffe/semaglutid.html"},{"slug":"semax","begriff":"Semax","begriff_en":"Semax","kategorie":"wirkstoff","kurz":"Synthetisch heptapeptide onderzocht in ratmodellen, onder andere onderzoek.","kurz_en":"Synthetisch heptapeptide onderzocht in ratmodellen, onder andere onderzoek.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 14556513","titel_en":"PubMed: Onderzoekspublicatie, PMID 14556513","url":"https://pubmed.ncbi.nlm.nih.gov/14556513/"}],"text":"De geciteerde publicatie onderzoekt BDNF in verschillende hersengebieden van ratten. Dit zijn pre-klinische gegevens. Ze vestigen geen cognitieve verbetering bij mensen.","text_en":"De geciteerde publicatie onderzoekt BDNF in verschillende hersengebieden van ratten. Dit zijn pre-klinische gegevens. Ze vestigen geen cognitieve verbetering bij mensen.","link":"wirkstoffe/semax.html"},{"slug":"sequenz","begriff":"Sequentie","begriff_en":"Sequentie","kategorie":"grundlagen","kurz":"De vaste volgorde van aminozuren in een peptide of eiwitketen.","kurz_en":"De vaste volgorde van aminozuren in een peptide of eiwitketen.","quellen":[{"titel":"Alberts et al.: Proteïnestructuur","titel_en":"Alberts et al.: Proteïnestructuur","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"De sequentie beschrijft de volgorde waarin de individuele aminozuren worden aan elkaar gekoppeld via peptidebindingen. Deze wordt meestal geschreven met gestandaardiseerde een- of drieledige codes per aminozuur. Twee peptiden gemaakt van dezelfde aminozuren maar in een andere volgorde tellen als verschillende moleculen, wat de sequentie een sleutelidentiteitsmarker maakt.","text_en":"De sequentie beschrijft de volgorde waarin de individuele aminozuren worden aan elkaar gekoppeld via peptidebindingen. Deze wordt meestal geschreven met gestandaardiseerde een- of drieledige codes per aminozuur. Twee peptiden gemaakt van dezelfde aminozuren maar in een andere volgorde tellen als verschillende moleculen, wat de sequentie een sleutelidentiteitsmarker maakt.","synonyme":["Aminozuursequentie"],"synonyme_en":["Aminozuursequentie"],"siehe":["aminosaeure","peptidbindung","identitaet"]},{"slug":"sermorelin","begriff":"Sermoreline","begriff_en":"Sermoreline","kategorie":"wirkstoff","kurz":"GHRH-afgeleid peptide onderzocht in endocriene onderzoek.","kurz_en":"GHRH-afgeleid peptide onderzocht in endocriene onderzoek.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 18031173","titel_en":"PubMed: Onderzoekspublicatie, PMID 18031173","url":"https://pubmed.ncbi.nlm.nih.gov/18031173/"}],"text":"De gelinkte review plaatst sermoreline in het historische onderzoek naar kindervergroeihormoontekort. Historische medische literatuur vestigt noch de huidige autorisatiedstatus noch de kwaliteit van een winkelproduct.","text_en":"De gelinkte review plaatst sermoreline in het historische onderzoek naar kindervergroeihormoontekort. Historische medische literatuur vestigt noch de huidige autorisatiedstatus noch de kwaliteit van een winkelproduct.","synonyme":["GRF 1-29","GHRH(1-29)","Geref (historische merknaam)"],"synonyme_en":["GRF 1-29","GHRH(1-29)","Geref (historische merknaam)"],"link":"wirkstoffe/sermorelin.html"},{"slug":"ss-31","begriff":"SS-31 (elamipretide)","begriff_en":"SS-31 (elamipretide)","kategorie":"wirkstoff","kurz":"Elamipretide, een synthetisch peptide onderzocht in studies naar mitochondriale aandoeningen.","kurz_en":"Elamipretide, een synthetisch peptide onderzocht in studies naar mitochondriale aandoeningen.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 37268435","titel_en":"PubMed: Onderzoekspublicatie, PMID 37268435","url":"https://pubmed.ncbi.nlm.nih.gov/37268435/"},{"titel":"FDA: Forzinity, goedgekeurd 19 September 2025","titel_en":"FDA: Forzinity, goedgekeurd 19 September 2025","url":"https://www.fda.gov/drugs/drug-trials-snapshots/drug-trials-snapshots-forzinity"}],"text":"Op 19 September 2025 verleende de FDA versnelde goedkeuring aan Forzinity, dat elamipretide bevat, voor een gedefinieerde patiëntengroep met Barth syndroom. Deze Amerikaanse productgoedkeuring is niet van toepassing op onderzoekschemicalia die worden verkocht als SS-31.","text_en":"Op 19 September 2025 verleende de FDA versnelde goedkeuring aan Forzinity, dat elamipretide bevat, voor een gedefinieerde patiëntengroep met Barth syndroom. Deze Amerikaanse productgoedkeuring is niet van toepassing op onderzoekschemicalia die worden verkocht als SS-31.","synonyme":["Elamipretide","MTP-131","Bendavia"],"synonyme_en":["Elamipretide","MTP-131","Bendavia"],"link":"wirkstoffe/ss-31.html"},{"slug":"steriles-wasser","begriff":"Steriel water","begriff_en":"Steriel water","kategorie":"handhabung","kurz":"Water waarvoor steriliteit een gespecificeerd productkenmerk is.","kurz_en":"Water waarvoor steriliteit een gespecificeerd productkenmerk is.","quellen":[{"titel":"FDA: Steriliteit en endotoxinen","titel_en":"FDA: Steriliteit en endotoxinen","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-technical-guides/bacterial-endotoxinspyrogens"}],"text":"Steriliteit en vrijheid van endotoxinen zijn verschillende eigenschappen. Producten moeten worden beoordeeld aan de hand van hun specificaties; het woord “steriel” impliceert noch universele geschiktheid als oplosmiddel noch een specifieke houdbaarheid na opening.","text_en":"Steriliteit en vrijheid van endotoxinen zijn verschillende eigenschappen. Producten moeten worden beoordeeld aan de hand van hun specificaties; het woord “steriel” impliceert noch universele geschiktheid als oplosmiddel noch een specifieke houdbaarheid na opening.","siehe":["bakteriostatisches-wasser","rekonstitution","sterilitaet"]},{"slug":"sterilitaet","begriff":"Steriliteit","begriff_en":"Steriliteit","kategorie":"labor","kurz":"Steriliteit beschrijft de afwezigheid van levende micro-organismen in een monster, gecontroleerd via een eigen, aangewezen labtest.","kurz_en":"Steriliteit beschrijft de afwezigheid van levende micro-organismen in een monster, gecontroleerd via een eigen, aangewezen labtest.","quellen":[{"titel":"FDA: Steriliteitstesten en procescontrole","titel_en":"FDA: Steriliteitstesten en procescontrole","url":"https://www.fda.gov/drugs/guidances-drugs/questions-and-answers-current-good-manufacturing-practice-regulations-production-and-process"}],"text":"De test is onafhankelijk van zuiverheid, identiteit en endotoxinewaarde, en wordt apart gedocumenteerd. Het is voornamelijk van belang voor lyofyliseerde peptiden die worden opgelost en verder worden behandeld in een laboratoriumomgeving.","text_en":"De test is onafhankelijk van zuiverheid, identiteit en endotoxinewaarde, en wordt apart gedocumenteerd. Het is voornamelijk van belang voor lyofyliseerde peptiden die worden opgelost en verder worden behandeld in een laboratoriumomgeving.","siehe":["endotoxin","coa"]},{"slug":"confounder","begriff":"Confounder","begriff_en":"Confounder","kategorie":"studien","kurz":"Factor die verband houdt met zowel de uitkomst als het onderzochte kenmerk en een associatie kan vertekenen of voorwenden.","kurz_en":"Factor die verband houdt met zowel de uitkomst als het onderzochte kenmerk en een associatie kan vertekenen of voorwenden.","quellen":[{"titel":"NLM MeSH: Confounding Factors, Epidemiologic","titel_en":"NLM MeSH: Confounding Factors, Epidemiologic","url":"https://www.ncbi.nlm.nih.gov/mesh/68015986"}],"text":"Een confounder kan de onderzochte uitkomst veroorzaken of voorkomen zonder een tussenstap van het onderzochte kenmerk te zijn. Hij hangt ook samen met dat kenmerk en kan een associatie vertekenen of creëren. Voorbeeld: koffiedrinkers roken gemiddeld vaker, dus een longaandoening zou ten onrechte aan koffie kunnen worden toegeschreven. Studies houden rekening met confounders door willekeurige toewijzing of statistische correctie.","text_en":"Een confounder kan de onderzochte uitkomst veroorzaken of voorkomen zonder een tussenstap van het onderzochte kenmerk te zijn. Hij hangt ook samen met dat kenmerk en kan een associatie vertekenen of creëren. Voorbeeld: koffiedrinkers roken gemiddeld vaker, dus een longaandoening zou ten onrechte aan koffie kunnen worden toegeschreven. Studies houden rekening met confounders door willekeurige toewijzing of statistische correctie.","synonyme":["Verstorende factor","Verstorende variabele"],"synonyme_en":["Verstorende factor","Verstorende variabele"],"siehe":["association","observational-study","rct"],"seiten":["studien.html"]},{"slug":"studienphasen","begriff":"Proeffasen","begriff_en":"Proeffasen","kategorie":"studien","kurz":"De vier stadia van klinische testen: fase I tot III vóór goedkeuring, fase IV daarna in dagelijks gebruik.","kurz_en":"De vier stadia van klinische testen: fase I tot III vóór goedkeuring, fase IV daarna in dagelijks gebruik.","quellen":[{"titel":"FDA: Fasen van klinisch onderzoek","titel_en":"FDA: Fasen van klinisch onderzoek","url":"https://www.fda.gov/patients/drug-development-process/step-3-clinical-research"}],"text":"Klinische ontwikkeling wordt vaak beschreven in vier fasen: Fase I onderzoekt voornamelijk veiligheid en tolerantie bij gezonde vrijwilligers of patiënten. Fase II onderzoekt initieel bewijs van effectiviteit en verdere veiligheidsvragen. Fase III onderzoekt dit in grotere groepen. Fase IV omvat studies na goedkeuring. De fase alleen stelt de kwaliteit van een individuele studie niet vast.","text_en":"Klinische ontwikkeling wordt vaak beschreven in vier fasen: Fase I onderzoekt voornamelijk veiligheid en tolerantie bij gezonde vrijwilligers of patiënten. Fase II onderzoekt initieel bewijs van effectiviteit en verdere veiligheidsvragen. Fase III onderzoekt dit in grotere groepen. Fase IV omvat studies na goedkeuring. De fase alleen stelt de kwaliteit van een individuele studie niet vast.","synonyme":["Fasen I tot IV"],"synonyme_en":["Fasen I tot IV"],"siehe":["klinische-studie","rct"],"seiten":["studien.html"]},{"slug":"survodutid","begriff":"Survodutide","begriff_en":"Survodutide","kategorie":"wirkstoff","kurz":"Dubbele glucagon en GLP-1 receptor agonist onderzocht in klinische proeven.","kurz_en":"Dubbele glucagon en GLP-1 receptor agonist onderzocht in klinische proeven.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 38330987","titel_en":"PubMed: Onderzoekspublicatie, PMID 38330987","url":"https://pubmed.ncbi.nlm.nih.gov/38330987/"}],"text":"De gelinkte fase II proef onderzoekt survodutide als een dubbele receptor agonist. Proefgegevens betreffen de geteste formulering en populatie en verifiëren de kwaliteit van onderzoekschemische niet.","text_en":"De gelinkte fase II proef onderzoekt survodutide als een dubbele receptor agonist. Proefgegevens betreffen de geteste formulering en populatie en verifiëren de kwaliteit van onderzoekschemische niet.","synonyme":["BI 456906"],"synonyme_en":["BI 456906"],"link":"wirkstoffe/survodutid.html"},{"slug":"tb-500","begriff":"TB-500","begriff_en":"TB-500","kategorie":"wirkstoff","kurz":"Een naam gebruikt in een origineel analytisch artikel voor een geacetyleerd fragment van thymosine beta-4.","kurz_en":"Een naam gebruikt in een origineel analytisch artikel voor een geacetyleerd fragment van thymosine beta-4.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 23084823","titel_en":"PubMed: Onderzoekspublicatie, PMID 23084823","url":"https://pubmed.ncbi.nlm.nih.gov/23084823/"}],"text":"Het gelinkte analytische artikel identificeert een geacetyleerd fragment in een product gelabeld TB-500. Bevindingen voor full-length thymosine beta-4 gelden niet automatisch voor dit fragment of andere verhandelde producten.","text_en":"Het gelinkte analytische artikel identificeert een geacetyleerd fragment in een product gelabeld TB-500. Bevindingen voor full-length thymosine beta-4 gelden niet automatisch voor dit fragment of andere verhandelde producten.","synonyme":["Thymosine-bèta-4-fragment","TB4 Frag"],"synonyme_en":["Thymosine-bèta-4-fragment","TB4 Frag"],"link":"wirkstoffe/tb-500.html"},{"slug":"tesamorelin","begriff":"Tesamoreline","begriff_en":"Tesamoreline","kategorie":"wirkstoff","kurz":"Synthetisch groeihormoon-vrijmakend factor analoog onderzocht in klinische proeven.","kurz_en":"Synthetisch groeihormoon-vrijmakend factor analoog onderzocht in klinische proeven.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 18057338","titel_en":"PubMed: Onderzoekspublicatie, PMID 18057338","url":"https://pubmed.ncbi.nlm.nih.gov/18057338/"}],"text":"Het geciteerde klinische artikel onderzoekt een groeihormoon-vrijmakend factor bij mensen met HIV. De klinische context en studievoorbereiding beperken hoe bevindingen gegeneraliseerd kunnen worden.","text_en":"Het geciteerde klinische artikel onderzoekt een groeihormoon-vrijmakend factor bij mensen met HIV. De klinische context en studievoorbereiding beperken hoe bevindingen gegeneraliseerd kunnen worden.","synonyme":["Egrifta","TH9507","Egrifta WR"],"synonyme_en":["Egrifta","TH9507","Egrifta WR"],"link":"wirkstoffe/tesamorelin.html"},{"slug":"thymosin-alpha-1","begriff":"Thymosine alfa 1","begriff_en":"Thymosine alfa 1","kategorie":"wirkstoff","kurz":"Peptide uit het thymosin systeem onderzocht in klinische en preklinische studies.","kurz_en":"Peptide uit het thymosin systeem onderzocht in klinische en preklinische studies.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 3998766","titel_en":"PubMed: Onderzoekspublicatie, PMID 3998766","url":"https://pubmed.ncbi.nlm.nih.gov/3998766/"}],"text":"De gelinkte gerandomiseerde studie onderzoekt synthetisch thymosin alfa-1 in een specifieke oncologische context. Een dergelijk bevinding is geen algemeen bewijs van immuunversterking en verifieert niet vrij verkrijgbare onderzoeksproducten.","text_en":"De gelinkte gerandomiseerde studie onderzoekt synthetisch thymosin alfa-1 in een specifieke oncologische context. Een dergelijk bevinding is geen algemeen bewijs van immuunversterking en verifieert niet vrij verkrijgbare onderzoeksproducten.","synonyme":["Tα1","Zadaxin (merknaam)"],"synonyme_en":["Tα1","Zadaxin (merknaam)"],"link":"wirkstoffe/thymosin-alpha-1.html"},{"slug":"thymosine","begriff":"Thymosins","begriff_en":"Thymosins","kategorie":"klassen","kurz":"Thymosins zijn een familie van peptiden oorspronkelijk geïsoleerd uit de thymusklier.","kurz_en":"Thymosins zijn een familie van peptiden oorspronkelijk geïsoleerd uit de thymusklier.","quellen":[{"titel":"NCI: thymosinen","titel_en":"NCI: thymosinen","url":"https://www.cancer.gov/publications/dictionaries/cancer-drug/def/recombinant-thymosin"}],"text":"De naam omvat verschillende peptiden oorspronkelijk geïsoleerd uit thymusmateriaal. Alfa en beta thymosins verschillen in structuur en onderzoekscontext. Bevindingen voor één thymosin gelden niet automatisch voor andere.","text_en":"De naam omvat verschillende peptiden oorspronkelijk geïsoleerd uit thymusmateriaal. Alfa en beta thymosins verschillen in structuur en onderzoekscontext. Bevindingen voor één thymosin gelden niet automatisch voor andere.","synonyme":["Thymosin peptiden"],"synonyme_en":["Thymosin peptiden"],"siehe":["peptidhormon","protein"],"wirkstoffe":["thymosin-alpha-1","tb-500"],"seiten":["peptid-1x1.html"]},{"slug":"tiermodell","begriff":"Diermodel","begriff_en":"Diermodel","kategorie":"studien","kurz":"Een laboratoriumdier, zoals een muis of rat, wordt gebruikt om een stof in vivo te bestuderen. Geen direct bewijs voor mensen.","kurz_en":"Een laboratoriumdier, zoals een muis of rat, wordt gebruikt om een stof in vivo te bestuderen. Geen direct bewijs voor mensen.","quellen":[{"titel":"NCI: diermodel","titel_en":"NCI: diermodel","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/animal-model"}],"text":"Een diermodel is een laboratoriumdier zoals een muis, rat of zebravis waarin metabolisme, gedrag of weefsel wordt bestudeerd onder gecontroleerde omstandigheden. Het dient voor pre-klinisch onderzoek voordat een klinische proef mogelijk is. Omdat genetica en fysiologie verschillen, is een effect in een diermodel geen bewijs van een effect bij mensen.","text_en":"Een diermodel is een laboratoriumdier zoals een muis, rat of zebravis waarin metabolisme, gedrag of weefsel wordt bestudeerd onder gecontroleerde omstandigheden. Het dient voor pre-klinisch onderzoek voordat een klinische proef mogelijk is. Omdat genetica en fysiologie verschillen, is een effect in een diermodel geen bewijs van een effect bij mensen.","siehe":["in-vivo","praeklinisch"],"seiten":["studien.html"]},{"slug":"tirzepatid","begriff":"Tirzepatide","begriff_en":"Tirzepatide","kategorie":"wirkstoff","kurz":"Dual GIP en GLP-1 receptor agonist bestudeerd in klinische proeven.","kurz_en":"Dual GIP en GLP-1 receptor agonist bestudeerd in klinische proeven.","quellen":[{"titel":"PubMed: Onderzoekspublicatie, PMID 35658024","titel_en":"PubMed: Onderzoekspublicatie, PMID 35658024","url":"https://pubmed.ncbi.nlm.nih.gov/35658024/"}],"text":"De gelinkte gerandomiseerde klinische proef onderzoekt tirzepatide bij obesitas. De studieformulering en kwaliteitscontroles moeten worden onderscheiden van vrij verhandelde onderzoekschemicalia.","text_en":"De gelinkte gerandomiseerde klinische proef onderzoekt tirzepatide bij obesitas. De studieformulering en kwaliteitscontroles moeten worden onderscheiden van vrij verhandelde onderzoekschemicalia.","synonyme":["LY3298176"],"synonyme_en":["LY3298176"],"link":"wirkstoffe/tirzepatid.html"},{"slug":"u-100","begriff":"U-100","begriff_en":"U-100","kategorie":"handhabung","kurz":"Een aanduiding voor insuline met 100 eenheden per milliliter, niet een algemene peptide-eenheid.","kurz_en":"Een aanduiding voor insuline met 100 eenheden per milliliter, niet een algemene peptide-eenheid.","quellen":[{"titel":"DailyMed: Betekenis van de U-100 aanduiding","titel_en":"DailyMed: Betekenis van de U-100 aanduiding","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c8ecbd7a-0e22-4fc7-a503-faa58c1b6f3f"}],"text":"U-100 is een concentratieaanduiding voor insulineproducten. Het is geen algemene eenheid van peptide massa. Een schaal die op deze manier is gelabeld kan niet geïnterpreteerd worden als een peptidehoeveelheid zonder de stof en zijn specificatie te kennen.","text_en":"U-100 is een concentratieaanduiding voor insulineproducten. Het is geen algemene eenheid van peptide massa. Een schaal die op deze manier is gelabeld kan niet geïnterpreteerd worden als een peptidehoeveelheid zonder de stof en zijn specificatie te kennen.","siehe":["internationale-einheit","konzentration"]},{"slug":"vial","begriff":"Fles","begriff_en":"Fles","kategorie":"handhabung","kurz":"Een flesje is een klein glazen container, meestal afgesloten met een rubberen dop, die een peptide als poeder of oplossing bevat.","kurz_en":"Een flesje is een klein glazen container, meestal afgesloten met een rubberen dop, die een peptide als poeder of oplossing bevat.","quellen":[{"titel":"ICH Q7: Productie, batches en analysecertificaten","titel_en":"ICH Q7: Productie, batches en analysecertificaten","url":"https://www.fda.gov/media/71518/download"}],"text":"Flessen zijn de standaardverpakking voor lyophilisatere peptiden in de onderzoekshandel. De rubberen dop maakt een afgesloten verwijdering mogelijk, en het afgedrukte etiket vermeldt meestal het batchnummer en de hoeveelheid. Een enkel flesje kan overeenkomen met een CoA zolang het batchnummer overeenkomt.","text_en":"Flessen zijn de standaardverpakking voor lyophilisatere peptiden in de onderzoekshandel. De rubberen dop maakt een afgesloten verwijdering mogelijk, en het afgedrukte etiket vermeldt meestal het batchnummer en de hoeveelheid. Een enkel flesje kan overeenkomen met een CoA zolang het batchnummer overeenkomt.","synonyme":["Klein flesje"],"synonyme_en":["Klein flesje"],"siehe":["charge","lyophilisat","aliquot"]},{"slug":"wachstumshormon","begriff":"Groeihormoon","begriff_en":"Groeihormoon","kategorie":"klassen","kurz":"Groeihormoon is een hypofyne hormoon dat groei, metabolisme en lichaamssamenstelling reguleert.","kurz_en":"Groeihormoon is een hypofyne hormoon dat groei, metabolisme en lichaamssamenstelling reguleert.","quellen":[{"titel":"NIDDK: Groeihormoon en IGF-1","titel_en":"NIDDK: Groeihormoon en IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Somatotropine","langform_en":"Somatotropine","text":"Groeihormoon, ook wel somatotropine of GH genoemd, wordt geproduceerd door somatotrofe cellen in de hypofyse en wordt in pulsen vrijgegeven in het bloed, gecontroleerd door GHRH, somatostatin en ghreline. Het reguleert longitudinale groei, spier- en vetmetabolisme en botdichtheid, zowel direct als via IGF-1 uit de lever. Verschillende peptideklassen richten zich op verschillende punten langs deze as, inclusief de afgifte uit de anterieure hypofyse.","text_en":"Groeihormoon, ook wel somatotropine of GH genoemd, wordt geproduceerd door somatotrofe cellen in de hypofyse en wordt in pulsen vrijgegeven in het bloed, gecontroleerd door GHRH, somatostatin en ghreline. Het reguleert longitudinale groei, spier- en vetmetabolisme en botdichtheid, zowel direct als via IGF-1 uit de lever. Verschillende peptideklassen richten zich op verschillende punten langs deze as, inclusief de afgifte uit de anterieure hypofyse.","synonyme":["GH","HGH","Somatotropine"],"synonyme_en":["GH","HGH","Somatotropine"],"siehe":["ghrh","ghrp","igf-1"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin","ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"wada","begriff":"WADA","begriff_en":"WADA","kategorie":"recht","kurz":"WADA publiceert een jaarlijkse verbodenlijst voor sport die ook peptiden omvat.","kurz_en":"WADA publiceert een jaarlijkse verbodenlijst voor sport die ook peptiden omvat.","quellen":[{"titel":"WADA: Huidige verbodenlijst","titel_en":"WADA: Huidige verbodenlijst","url":"https://www.wada-ama.org/en/prohibited-list"}],"langform":"Wereld Anti-Doping Agentschap","langform_en":"Wereld Anti-Doping Agentschap","text":"De World Anti-Doping Agency coördineert anti-dopingregels in georganiseerde sport en werkt zijn verbodenlijst jaarlijks bij. Verschillende categorieën dekken peptidehormonen en gerelateerde stoffen, onafhankelijk van hun wettelijke status buiten sport. Welke specifieke stof wordt gedekt, staat alleen in de huidige WADA lijst zelf.","text_en":"De World Anti-Doping Agency coördineert anti-dopingregels in georganiseerde sport en werkt zijn verbodenlijst jaarlijks bij. Verschillende categorieën dekken peptidehormonen en gerelateerde stoffen, onafhankelijk van hun wettelijke status buiten sport. Welke specifieke stof wordt gedekt, staat alleen in de huidige WADA lijst zelf.","seiten":["faq.html"]},{"slug":"zulassung","begriff":"Vergunning voor het in de handel brengen","begriff_en":"Vergunning voor het in de handel brengen","kategorie":"recht","kurz":"Een vergunning voor het in de handel brengen is de regelgevende goedkeuring die nodig is om een geneesmiddel op een markt te verkopen.","kurz_en":"Een vergunning voor het in de handel brengen is de regelgevende goedkeuring die nodig is om een geneesmiddel op een markt te verkopen.","quellen":[{"titel":"EMA: Evaluatie en autorisaties","titel_en":"EMA: Evaluatie en autorisaties","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"text":"In de gecentraliseerde EU-procedure beoordeelt de EMA het wetenschappelijke dossier. De Europese Commissie verleent de vergunning voor het in de handel brengen. De vergunning geldt voor een specifiek geneesmiddel onder gespecificeerde voorwaarden, niet voor elk product met dezelfde stofnaam.","text_en":"In de gecentraliseerde EU-procedure beoordeelt de EMA het wetenschappelijke dossier. De Europese Commissie verleent de vergunning voor het in de handel brengen. De vergunning geldt voor een specifiek geneesmiddel onder gespecificeerde voorwaarden, niet voor elk product met dezelfde stofnaam.","synonyme":["Vergunning voor het in de handel brengen"],"synonyme_en":["Vergunning voor het in de handel brengen"],"siehe":["ema","fda","arzneimittel"],"seiten":["peptid-1x1.html"]}];
